import * as THREE from "three";

/**
 * The single source of truth for "how high is the ground at (x, z)".
 *
 * It reads the *same* Float32Array that was written into the plane's
 * position attribute - not the raw noise, not a re-generated heightmap, not
 * a per-frame raycast - and interpolates it with the exact same triangle
 * split PlaneGeometry uses. That means heightAt doesn't approximate the
 * mesh: within floating-point error it *is* the mesh surface, which is what
 * verifyAgainstMesh exists to prove.
 *
 * Anything that needs to sit on the mountain (trail, flags, camera
 * clearance) goes through here. If a second height lookup ever appears
 * somewhere else, the two will drift and things start floating.
 */

export interface TerrainSamplerOptions {
  /**
   * Per-vertex world-space Y, row-major (z outer, x inner), exactly as
   * written into the geometry - post-falloff, post-scale, post-blur.
   */
  heights: Float32Array;
  /** Vertices per side, i.e. segments + 1. */
  resolution: number;
  /** World-space extent of the plane along X. */
  width: number;
  /** World-space extent of the plane along Z. */
  depth: number;
}

export interface VerifySampleError {
  x: number;
  z: number;
  sampled: number;
  mesh: number;
  error: number;
}

export interface VerifyReport {
  /** Rays that actually hit the mesh and were compared. */
  samples: number;
  /** Rays that missed entirely (outside the mesh, or a hole in it). */
  misses: number;
  maxError: number;
  meanError: number;
  rmsError: number;
  /** The single worst disagreement found. */
  worst: VerifySampleError | null;
  /** True when maxError is within tolerance - i.e. the sampler is the mesh. */
  pass: boolean;
  tolerance: number;
}

/** Deterministic PRNG so a verify run is reproducible between reloads. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export class TerrainSampler {
  readonly resolution: number;
  readonly width: number;
  readonly depth: number;
  /** World units between adjacent vertices. */
  readonly cellX: number;
  readonly cellZ: number;

  private readonly heights: Float32Array;
  private readonly halfWidth: number;
  private readonly halfDepth: number;
  private readonly minY: number;
  private readonly maxY: number;

  private readonly scratchRay = new THREE.Raycaster();
  private readonly scratchOrigin = new THREE.Vector3();
  private readonly down = new THREE.Vector3(0, -1, 0);

  constructor(options: TerrainSamplerOptions) {
    const { heights, resolution, width, depth } = options;
    if (heights.length !== resolution * resolution) {
      throw new Error(
        `TerrainSampler: heights has ${heights.length} entries, expected ${resolution * resolution}`,
      );
    }
    this.heights = heights;
    this.resolution = resolution;
    this.width = width;
    this.depth = depth;
    this.halfWidth = width / 2;
    this.halfDepth = depth / 2;
    this.cellX = width / (resolution - 1);
    this.cellZ = depth / (resolution - 1);

    let minY = Infinity;
    let maxY = -Infinity;
    for (let i = 0; i < heights.length; i++) {
      if (heights[i] < minY) minY = heights[i];
      if (heights[i] > maxY) maxY = heights[i];
    }
    this.minY = minY;
    this.maxY = maxY;
  }

  /**
   * World-space surface height at (x, z), clamped to the plane's extent.
   *
   * PlaneGeometry emits each quad as (a, b, d) + (b, c, d) with
   * a = (ix, iz), b = (ix, iz + 1), c = (ix + 1, iz + 1), d = (ix + 1, iz) -
   * so the diagonal runs b–d and which triangle a point falls in is decided
   * by fx + fz against 1. Interpolating on that exact split (rather than
   * bilinearly across the quad) is what makes this agree with a raycast to
   * within float precision instead of "close enough, usually".
   *
   * Row index maps to +Z: PlaneGeometry's local +Y becomes -Z under
   * rotateX(-PI/2), and its rows run from +Y downward, so row 0 lands at
   * z = -depth/2 and the last row at z = +depth/2.
   */
  heightAt(x: number, z: number): number {
    const res = this.resolution;
    const last = res - 1;

    let gx = ((x + this.halfWidth) / this.width) * last;
    let gz = ((z + this.halfDepth) / this.depth) * last;
    gx = gx < 0 ? 0 : gx > last ? last : gx;
    gz = gz < 0 ? 0 : gz > last ? last : gz;

    const ix = Math.min(res - 2, Math.floor(gx));
    const iz = Math.min(res - 2, Math.floor(gz));
    const fx = gx - ix;
    const fz = gz - iz;

    const row0 = iz * res + ix;
    const row1 = row0 + res;
    const ha = this.heights[row0];
    const hd = this.heights[row0 + 1];
    const hb = this.heights[row1];
    const hc = this.heights[row1 + 1];

    return fx + fz <= 1
      ? ha + fx * (hd - ha) + fz * (hb - ha)
      : hc + (1 - fx) * (hb - hc) + (1 - fz) * (hd - hc);
  }

  /**
   * Surface normal at (x, z), by central difference over `epsilon` world
   * units. Deliberately not the per-triangle face normal: at these cell
   * sizes a face normal flips from facet to facet and anything offset along
   * it visibly jitters between samples. One cell of central difference reads
   * the same exact surface but varies smoothly along a path.
   */
  normalAt(
    x: number,
    z: number,
    epsilon = Math.max(this.cellX, this.cellZ),
    target?: THREE.Vector3,
  ): THREE.Vector3 {
    const out = target ?? new THREE.Vector3();
    const dx = (this.heightAt(x + epsilon, z) - this.heightAt(x - epsilon, z)) / (2 * epsilon);
    const dz = (this.heightAt(x, z + epsilon) - this.heightAt(x, z - epsilon)) / (2 * epsilon);
    return out.set(-dx, 1, -dz).normalize();
  }

  /**
   * A point sitting `offset` world units off the surface at (x, z), measured
   * along the surface normal - real perpendicular clearance, so a line keeps
   * the same visual gap on a steep flank as it does on flat ground.
   * `offset = 0` returns the surface point itself.
   */
  pointOnSurface(x: number, z: number, offset = 0, target?: THREE.Vector3): THREE.Vector3 {
    const out = target ?? new THREE.Vector3();
    out.set(x, this.heightAt(x, z), z);
    if (offset !== 0) out.addScaledVector(this.normalAt(x, z), offset);
    return out;
  }

  /**
   * Fires rays straight down at the real mesh and compares each hit to
   * heightAt at the same XZ. This is the check that says whether a floating
   * trail is the sampler's fault (a flipped axis, a stale array, a scale
   * applied twice) or the trail's own offset - run it before touching any
   * offset.
   */
  verifyAgainstMesh(
    mesh: THREE.Object3D,
    options: { samples?: number; seed?: number; tolerance?: number; log?: boolean } = {},
  ): VerifyReport {
    const { samples = 128, seed = 20250820, tolerance = 0.01, log = true } = options;

    mesh.updateMatrixWorld(true);
    const rand = mulberry32(seed);
    const rayHeight = this.maxY + Math.max(10, (this.maxY - this.minY) * 0.5);
    // Inset by one cell: a ray at the exact border can pass the edge
    // triangle tangentially and miss, which would be noise, not signal.
    const insetX = this.halfWidth - this.cellX;
    const insetZ = this.halfDepth - this.cellZ;

    const errors: VerifySampleError[] = [];
    let misses = 0;
    let sum = 0;
    let sumSq = 0;
    let maxError = 0;
    let worst: VerifySampleError | null = null;

    for (let i = 0; i < samples; i++) {
      const x = (rand() * 2 - 1) * insetX;
      const z = (rand() * 2 - 1) * insetZ;

      this.scratchOrigin.set(x, rayHeight, z);
      this.scratchRay.set(this.scratchOrigin, this.down);
      this.scratchRay.far = rayHeight - this.minY + 1;
      const hits = this.scratchRay.intersectObject(mesh, true);
      if (hits.length === 0) {
        misses++;
        continue;
      }

      const meshY = hits[0].point.y;
      const sampled = this.heightAt(x, z);
      const error = Math.abs(sampled - meshY);
      const record: VerifySampleError = { x, z, sampled, mesh: meshY, error };
      errors.push(record);
      sum += error;
      sumSq += error * error;
      if (error > maxError) {
        maxError = error;
        worst = record;
      }
    }

    const n = errors.length;
    const report: VerifyReport = {
      samples: n,
      misses,
      maxError,
      meanError: n > 0 ? sum / n : 0,
      rmsError: n > 0 ? Math.sqrt(sumSq / n) : 0,
      worst,
      pass: n > 0 && maxError <= tolerance,
      tolerance,
    };

    if (log) {
      const round = (v: number) => Math.round(v * 1e4) / 1e4;
      console.log(
        `[TerrainSampler.verifyAgainstMesh] ${report.pass ? "PASS" : "FAIL"} - ` +
          `${n} hits, ${misses} misses, max |dY| = ${round(maxError)}, ` +
          `mean = ${round(report.meanError)}, rms = ${round(report.rmsError)} ` +
          `(tolerance ${tolerance})`,
      );
      if (worst) {
        console.log(
          `  worst at x=${round(worst.x)} z=${round(worst.z)}: ` +
            `sampler ${round(worst.sampled)} vs mesh ${round(worst.mesh)} (delta ${round(worst.error)})`,
        );
      }
      const tail = errors.slice().sort((a, b) => b.error - a.error).slice(0, 5);
      if (tail.length > 0) {
        console.table(
          tail.map((e) => ({
            x: round(e.x),
            z: round(e.z),
            sampler: round(e.sampled),
            mesh: round(e.mesh),
            error: round(e.error),
          })),
        );
      }
    }

    return report;
  }
}
