import * as THREE from "three";

/**
 * A CPU port of the exact maths in three's Sky shader (the Preetham
 * analytic daylight model - the same one Babylon's SkyMaterial implements,
 * down to the turbidity/rayleigh/mie knob names).
 *
 * This exists so the scene can *ask* the sky what colour it is in a given
 * direction rather than guessing. Three things need that answer and all
 * three look wrong if it is approximated by hand:
 *
 *  - fog. The massif fades into fog long before the far plane, so whatever
 *    colour the fog is, is the colour the mountain's silhouette dissolves
 *    into. Any value that is not the sky's own horizon colour draws a halo
 *    around the peak.
 *  - the sun light. Direct sunlight is the sky's extinction term, which is
 *    why low sun is warm: the blue has been scattered out of it on the way
 *    in. Deriving it here means the key light reddens as the sun sets
 *    without anyone hand-picking a gradient.
 *  - the hemisphere fill, which is the sky seen from the ground.
 *
 * Everything here is in linear working space, pre-tone-mapping, which is
 * where three wants fog/light colours - so a fogged pixel and the sky pixel
 * next to it go through ACES together and land on the same value.
 */

// Constants lifted verbatim from Sky.SkyShader. Names match the GLSL so the
// two can be diffed against each other when three updates the shader.
const TOTAL_RAYLEIGH = [5.804542996261093e-6, 1.3562911419845635e-5, 3.0265902468824876e-5];
const MIE_CONST = [1.8399918514433978e14, 2.7798023919660528e14, 4.0790479543861094e14];
const CUTOFF_ANGLE = 1.6110731556870734;
const STEEPNESS = 1.5;
const EE = 1000.0;
const RAYLEIGH_ZENITH_LENGTH = 8.4e3;
const MIE_ZENITH_LENGTH = 1.25e3;
const THREE_OVER_SIXTEENPI = 0.05968310365946075;
const ONE_OVER_FOURPI = 0.07957747154594767;

/** The four Preetham knobs, i.e. everything that changes the atmosphere itself. */
export interface AtmosphereParams {
  turbidity: number;
  rayleigh: number;
  mieCoefficient: number;
  mieDirectionalG: number;
}

/**
 * The per-frame constants the sky's vertex shader would compute: scattering
 * coefficients and the sun's energy. Held in one reusable object because
 * this is evaluated every frame and none of it is worth allocating for.
 */
export interface Atmosphere {
  betaR: [number, number, number];
  betaM: [number, number, number];
  sunE: number;
  /** Unit vector. Kept alongside the coefficients it was derived with. */
  sunDirection: THREE.Vector3;
}

export function createAtmosphere(): Atmosphere {
  return {
    betaR: [0, 0, 0],
    betaM: [0, 0, 0],
    sunE: 0,
    sunDirection: new THREE.Vector3(0, 1, 0),
  };
}

/** GLSL sunIntensity(): the "earth shadow hack" that fades the sun out at the horizon. */
function sunIntensity(zenithAngleCos: number): number {
  const cos = THREE.MathUtils.clamp(zenithAngleCos, -1, 1);
  return EE * Math.max(0, 1 - Math.exp(-((CUTOFF_ANGLE - Math.acos(cos)) / STEEPNESS)));
}

/**
 * Relative optical depth along a ray at this zenith cosine - 1 straight up,
 * climbing steeply as the ray flattens toward the horizon, which is the
 * whole reason a low sun is red and a high one is white.
 */
function opticalDepth(zenithCos: number): number {
  const zenithAngle = Math.acos(Math.max(0, zenithCos));
  return 1 / (Math.cos(zenithAngle) + 0.15 * Math.pow(93.885 - THREE.MathUtils.radToDeg(zenithAngle), -1.253));
}

/**
 * Fills `out` with the scattering state for this sun position. Call once per
 * frame, then evaluate as many directions off it as needed.
 *
 * `sunDirection` must be the same unit vector handed to the shader's
 * sunPosition uniform. Length matters to the shader only through vSunfade,
 * which saturates for any sane sun distance - passing the unit vector is
 * what three's own examples do.
 */
export function updateAtmosphere(
  out: Atmosphere,
  sunDirection: THREE.Vector3,
  params: AtmosphereParams,
): Atmosphere {
  out.sunDirection.copy(sunDirection).normalize();
  out.sunE = sunIntensity(out.sunDirection.y);

  // vSunfade saturates to 1 for any sun above the horizon at unit distance,
  // so rayleighCoefficient is just `rayleigh`. Written out in full anyway:
  // the shader computes it, and a divergence here would be invisible until
  // someone moved the sun below the horizon.
  const sunFade = 1 - THREE.MathUtils.clamp(1 - Math.exp(out.sunDirection.y / 450000), 0, 1);
  const rayleighCoefficient = params.rayleigh - (1 - sunFade);

  // GLSL `10E-18` is 1e-17, not 1e-18.
  const c = params.turbidity * 0.2 * 1e-17;
  for (let i = 0; i < 3; i++) {
    out.betaR[i] = TOTAL_RAYLEIGH[i] * rayleighCoefficient;
    out.betaM[i] = 0.434 * c * MIE_CONST[i] * params.mieCoefficient;
  }
  return out;
}

/**
 * Direct sunlight after the atmosphere has taken its cut: the extinction
 * term Fex along the sun's own path. This is the *colour of the key light*,
 * and at unit scale it is also its relative strength - it falls off and
 * warms as the sun drops without a separate curve for either.
 */
export function sunExtinction(atmosphere: Atmosphere, out: THREE.Color): THREE.Color {
  const depth = opticalDepth(atmosphere.sunDirection.y);
  const sR = RAYLEIGH_ZENITH_LENGTH * depth;
  const sM = MIE_ZENITH_LENGTH * depth;
  out.setRGB(
    Math.exp(-(atmosphere.betaR[0] * sR + atmosphere.betaM[0] * sM)),
    Math.exp(-(atmosphere.betaR[1] * sR + atmosphere.betaM[1] * sM)),
    Math.exp(-(atmosphere.betaR[2] * sR + atmosphere.betaM[2] * sM)),
    THREE.LinearSRGBColorSpace,
  );
  return out;
}

/**
 * The sky's radiance looking along `direction` - the fragment shader's
 * `texColor`, minus the solar disc and the clouds.
 *
 * The disc is left out deliberately: this feeds fog and ambient, and a
 * 19000x spike would make the fog flash white the moment the camera swung
 * past the sun.
 */
export function skyRadiance(
  atmosphere: Atmosphere,
  direction: THREE.Vector3,
  params: AtmosphereParams,
  out: THREE.Color,
): THREE.Color {
  const dir = direction.clone().normalize();
  const depth = opticalDepth(dir.y);
  const sR = RAYLEIGH_ZENITH_LENGTH * depth;
  const sM = MIE_ZENITH_LENGTH * depth;

  const cosTheta = dir.dot(atmosphere.sunDirection);
  const rPhase = THREE_OVER_SIXTEENPI * (1 + Math.pow(cosTheta * 0.5 + 0.5, 2));
  const g = params.mieDirectionalG;
  const g2 = g * g;
  const mPhase = ONE_OVER_FOURPI * ((1 - g2) / Math.pow(1 - 2 * g * cosTheta + g2, 1.5));

  // How much of the sky is lit by the sun's own colour rather than by plain
  // Rayleigh blue - the shader's horizon-warming blend, which only kicks in
  // once the sun is low.
  const warm = THREE.MathUtils.clamp(Math.pow(1 - atmosphere.sunDirection.y, 5), 0, 1);

  const channel = (i: number) => {
    const betaR = atmosphere.betaR[i];
    const betaM = atmosphere.betaM[i];
    const fex = Math.exp(-(betaR * sR + betaM * sM));
    const scatter = (atmosphere.sunE * (betaR * rPhase + betaM * mPhase)) / (betaR + betaM);
    let lin = Math.pow(Math.max(0, scatter * (1 - fex)), 1.5);
    lin *= THREE.MathUtils.lerp(1, Math.pow(Math.max(0, scatter * fex), 0.5), warm);
    return (lin + 0.1 * fex) * 0.04;
  };

  out.setRGB(channel(0), channel(1) + 0.0003, channel(2) + 0.00075, THREE.LinearSRGBColorSpace);
  return out;
}
