import * as THREE from "three";
import { Sky } from "three/examples/jsm/objects/Sky.js";
import {
  createAtmosphere,
  skyRadiance,
  sunExtinction,
  updateAtmosphere,
  type AtmosphereParams,
} from "./sky-model";

/**
 * Every knob the sky and its sun have, in one flat object.
 *
 * It is flat and it is mutable on purpose: this is the object the ?sky
 * panel writes to, the object you can poke from the console, and the object
 * whose defaults get pasted back into this file once a look is settled.
 * Nothing caches a copy of it - update() reads it fresh every frame - so
 * anything set here is on screen on the next one.
 */
export interface SkyConfig {
  // --- the traverse ---------------------------------------------------- //
  /**
   * Sun elevation in degrees at each end of the climb, measured from the
   * horizon *through* the zenith: 0 is on the horizon ahead, 90 is straight
   * overhead, 180 is the horizon behind. So 45 -> 135 is a sun that comes
   * up one side, passes over the summit at the middle of the page, and
   * drops toward the far side by the end - which is also why the shadow the
   * massif throws sweeps across the terrain and changes sides as you read.
   */
  elevationStart: number;
  elevationEnd: number;
  /**
   * Compass bearing (degrees, from +Z toward +X) the sun rises from. The
   * arc runs from here at elevationStart to the opposite bearing at
   * elevationEnd. Set by default to run across the camera's view rather
   * than into or away from it, because a sun behind the lens throws the
   * mountain's shadow behind the mountain, where nobody can see it.
   */
  azimuth: number;
  /**
   * Live elevation, in degrees. Written from scroll progress every frame -
   * unless manualElevation is on, in which case this is the value and
   * scroll is ignored. That is the switch the ?sky panel throws.
   */
  elevation: number;
  manualElevation: boolean;

  // --- the atmosphere -------------------------------------------------- //
  /** Haze. Low is a thin alpine sky, high is a milky one. */
  turbidity: number;
  /** How blue the blue is. */
  rayleigh: number;
  mieCoefficient: number;
  /** Forward-scattering bias: how tight the glow around the sun is. */
  mieDirectionalG: number;
  /**
   * Overall sky brightness. The Preetham model outputs absolute radiance,
   * which lands around 5-35 in linear space - i.e. pure white through any
   * tone mapping curve exposed for a mountainside. This scales it back into
   * range without touching renderer exposure, which the terrain's lighting
   * is already balanced against. (Babylon's SkyMaterial calls the same knob
   * `luminance`.)
   */
  luminance: number;
  /** Draw the solar disc itself, not just its glow. */
  showSunDisc: boolean;

  // --- clouds ---------------------------------------------------------- //
  cloudCoverage: number;
  cloudDensity: number;
  cloudScale: number;
  cloudSpeed: number;
  cloudElevation: number;

  // --- what the sky does to the scene ---------------------------------- //
  /** Key light strength with the sun overhead. It dims itself as the sun drops. */
  sunIntensity: number;
  /** Hemisphere fill strength. */
  ambientIntensity: number;
  /**
   * Fog takes the sky's own horizon colour, so the massif dissolves into
   * exactly the value behind it instead of into a fixed token colour that
   * is now a different colour from the sky. Turning this off restores the
   * token-driven fog - and with it a visible halo around the peak.
   */
  fogFollowsSky: boolean;
  fogDensity: number;
  /**
   * How far above the horizon, in degrees, the fog colour is sampled from.
   *
   * Not zero, and the difference is the whole lower half of the page. The
   * Preetham horizon is the brightest value in the sky by a wide margin -
   * the last few degrees before it are where the optical depth runs away -
   * so fog sampled at exactly 0 comes back brighter than any sky the massif
   * is actually seen against, and the apron in front of it goes to white.
   * A few degrees up lands on the value the fogged-out terrain is really
   * standing in front of.
   */
  fogSkyPitch: number;
  /**
   * Final multiplier on that sampled colour. 1 is the honest answer and a
   * little under it is usually the better picture: fog is what the page's
   * copy sits on top of, and the sky is allowed to be brighter than the
   * thing text has to stay readable against.
   */
  fogBrightness: number;

  // --- shadows --------------------------------------------------------- //
  /** 0 removes the shadow without recompiling anything. 1 is full strength. */
  shadowIntensity: number;
  /**
   * Half-width of the sun's shadow camera, in world units. It has to cover
   * the massif *plus* the shadow it throws off the side of it, which at 45
   * degrees is as long as the mountain is tall.
   */
  shadowRadius: number;
  shadowBias: number;
  /**
   * Pushes the shadow lookup along the surface normal before sampling.
   * This is the one that matters here: the terrain both casts and receives,
   * and at 620 world units across a 2048 map a texel is half a world unit -
   * without this the whole massif comes back in acne.
   */
  shadowNormalBias: number;
  /**
   * Degrees of sun movement before the shadow map is re-rendered. The
   * massif is a two-million-triangle caster, so re-rendering it every frame
   * doubles the scene's triangle load for a shadow that moves a few world
   * units per degree. At rest this means no shadow pass at all.
   */
  shadowStepDeg: number;
}

export const DEFAULT_SKY_CONFIG: SkyConfig = {
  elevationStart: 30,
  elevationEnd: 160,
  azimuth: 90,
  elevation: 145,
  manualElevation: false,

  turbidity: 2.4,
  rayleigh: 2.2,
  mieCoefficient: 0.005,
  mieDirectionalG: 0.8,
  // 0.055, not the 0.1 that makes the best-looking sky in isolation. Fog
  // is sampled from this same sky, so the two move together - and the value
  // that lands the horizon where the page's copy is still readable over it
  // is dimmer than the value that makes the zenith bluest.
  luminance: 0.055,
  showSunDisc: true,

  cloudCoverage: 0.32,
  cloudDensity: 0.45,
  cloudScale: 0.0002,
  cloudSpeed: 0.0001,
  cloudElevation: 0.5,

  // Less than half the 2.4 the old fixed key light carried, and the sun's
  // new height is the whole reason: that light raked the massif from 8
  // degrees above the horizon, where most slopes catch it at a glancing
  // angle. A sun at 45 to 135 degrees hits the same slopes nearly square,
  // so the same number blows the mountain out to white.
  sunIntensity: 1.25,
  ambientIntensity: 0.42,
  fogFollowsSky: true,
  fogDensity: 0.0009,
  // Zero: the horizon is exactly where the fogged-out apron meets the sky,
  // and anything else draws a line along it. The knob is kept because the
  // trade is real - see fogSkyPitch - but the seam costs more than the
  // brightness does.
  fogSkyPitch: 0,
  fogBrightness: 1,

  shadowIntensity: 0.85,
  // 620, the massif's full footprint, not the 310 its half-width would
  // suggest. At 45 degrees a 170-unit peak throws its shadow 170 units past
  // its own base, so a frustum sized to the mountain clips the far end of
  // the very thing it is there to draw - and a clipped shadow does not
  // fade, it stops along a straight line across the plain.
  shadowRadius: 620,
  shadowBias: -0.0006,
  shadowNormalBias: 1.4,
  shadowStepDeg: 0.35,
};

export interface SkyRigOptions {
  scene: THREE.Scene;
  camera: THREE.PerspectiveCamera;
  worldSize: number;
  /** Bounce colour from below for the hemisphere fill - the terrain's own ground token. */
  groundColor: THREE.Color;
  /** Whether to build the shadow map at all. Off for mobile/software renderers. */
  shadows?: boolean;
  /** Shadow map side, in texels. */
  shadowMapSize?: number;
  /** Seeds DEFAULT_SKY_CONFIG - anything left out keeps its default. */
  config?: Partial<SkyConfig>;
}

export interface SkyRig {
  /** Live and mutable. See SkyConfig - every field takes effect on the next frame. */
  config: SkyConfig;
  sky: Sky;
  sun: THREE.DirectionalLight;
  ambient: THREE.HemisphereLight;
  /** Unit vector toward the sun, as of the last update(). Do not mutate. */
  sunDirection: THREE.Vector3;
  /** 0..1 along the climb. Drives config.elevation unless manualElevation is set. */
  setProgress: (t: number) => void;
  /** Re-reads config, moves the sun, relights the scene. Call once per frame, after the camera. */
  update: (elapsedSeconds?: number) => void;
  dispose: () => void;
}

/**
 * Converts an elevation/azimuth pair into a world direction.
 *
 * Elevation sweeps through the zenith rather than being folded at 90, so
 * 135 degrees is 45 degrees above the *opposite* horizon - which is what
 * lets a single 45 -> 135 number line describe a whole day's traverse.
 */
function sunDirectionFrom(
  elevationDeg: number,
  azimuthDeg: number,
  out: THREE.Vector3,
): THREE.Vector3 {
  const elevation = THREE.MathUtils.degToRad(elevationDeg);
  const azimuth = THREE.MathUtils.degToRad(azimuthDeg);
  const horizontal = Math.cos(elevation);
  return out
    .set(horizontal * Math.sin(azimuth), Math.sin(elevation), horizontal * Math.cos(azimuth))
    .normalize();
}

/**
 * Patches a `luminance` knob into three's Sky shader.
 *
 * Done by string replacement against a stock addon, so it is checked rather
 * than assumed: if a three upgrade renames the line, the sky silently falls
 * back to raw Preetham radiance - a white screen - and that is a much
 * harder thing to diagnose from the render than from a console warning.
 */
function addLuminanceUniform(material: THREE.ShaderMaterial, luminance: number): void {
  const marker = "gl_FragColor = vec4( texColor, 1.0 );";
  if (!material.fragmentShader.includes(marker)) {
    console.warn("[sky] Sky shader has changed shape - the luminance knob is not wired up.");
    return;
  }
  // skyLuminance, not luminance: three's tone mapping prologue is prepended
  // to this shader and already declares a `float luminance( vec3 )`. The
  // collision does not fail the build, it fails at link time - at which
  // point the sky is a black rectangle and the console is the only place
  // that says why.
  material.uniforms.skyLuminance = { value: luminance };
  material.fragmentShader = material.fragmentShader
    .replace("uniform float time;", "uniform float time;\n\t\tuniform float skyLuminance;")
    .replace(marker, "gl_FragColor = vec4( texColor * skyLuminance, 1.0 );");
}

/**
 * The sky, the sun, and everything downstream of where the sun is.
 *
 * One source of truth for the time of day: the sky dome, the key light's
 * direction, its colour and its strength, the shadow the massif throws, the
 * hemisphere fill and the fog all come off the same elevation. That is the
 * point of doing it here rather than as five separate things in
 * scene/index.ts - move the sun, and everything that should follow it does.
 *
 * The sky is three's `Sky`, i.e. the Preetham analytic daylight model. That
 * is the same model, with the same turbidity/rayleigh/mie knobs, that
 * Babylon's SkyMaterial implements - so a look developed against one
 * transfers to the other, while the site stays on the single engine it
 * already ships.
 */
export function createSkyRig(options: SkyRigOptions): SkyRig {
  const config: SkyConfig = { ...DEFAULT_SKY_CONFIG, ...options.config };
  const { scene, camera, worldSize } = options;

  const sky = new Sky();
  // Sized to sit inside the camera's far plane and re-centred on the camera
  // every frame, so it is always the same distance away. The shader works
  // off the view *direction* through each fragment, so re-centring moves
  // nothing in the picture - it only keeps the box from being clipped by a
  // far plane set for a mountain rather than for an atmosphere.
  sky.scale.setScalar(worldSize * 4);
  // It is centred on a camera that can be anywhere, and the viewer is
  // always inside it. Nothing is gained by testing it against the frustum.
  sky.frustumCulled = false;
  addLuminanceUniform(sky.material, config.luminance);
  scene.add(sky);

  const sunDirection = new THREE.Vector3(0, 1, 0);
  // Unit length, which is what the shader's sunPosition wants. The light is
  // placed at its own distance separately.
  const sunPosition = new THREE.Vector3(0, 1, 0);
  sky.material.uniforms.sunPosition.value = sunPosition;

  const sun = new THREE.DirectionalLight(0xffffff, config.sunIntensity);
  // Far enough out that the whole massif falls between the shadow camera's
  // near and far planes, close enough that the ortho frustum stays tight.
  // Nothing about a directional light's *lighting* depends on this
  // distance; only its shadow camera does.
  const sunDistance = worldSize * 1.6;
  sun.target.position.set(0, 0, 0);
  scene.add(sun.target);
  scene.add(sun);

  const shadowsOn = options.shadows ?? true;
  if (shadowsOn) {
    sun.castShadow = true;
    const size = options.shadowMapSize ?? 2048;
    sun.shadow.mapSize.set(size, size);
    sun.shadow.camera.near = Math.max(1, sunDistance - worldSize);
    sun.shadow.camera.far = sunDistance + worldSize;
    // Hand-driven from here on: see config.shadowStepDeg. The first
    // update() always fires one, because lastShadowElevation starts as NaN
    // and every comparison against NaN is false.
    sun.shadow.autoUpdate = false;
    sun.shadow.needsUpdate = true;
  }

  const ambient = new THREE.HemisphereLight(0xffffff, options.groundColor, config.ambientIntensity);
  scene.add(ambient);

  const atmosphere = createAtmosphere();
  const params: AtmosphereParams = {
    turbidity: config.turbidity,
    rayleigh: config.rayleigh,
    mieCoefficient: config.mieCoefficient,
    mieDirectionalG: config.mieDirectionalG,
  };

  const sunColor = new THREE.Color();
  const fogColor = new THREE.Color();
  const ambientColor = new THREE.Color();
  const viewDirection = new THREE.Vector3();
  const sampleDirection = new THREE.Vector3();

  // Direct sunlight at the zenith, as luminance. Dividing by it turns the
  // extinction term into a 0..1 falloff, so config.sunIntensity means "the
  // strength at noon" and the dimming toward either horizon is the model's
  // rather than a second curve invented here.
  const ZENITH_SUN_LUMINANCE = 0.786;

  let progress = 0;
  let lastShadowElevation = Number.NaN;
  let lastShadowRadius = Number.NaN;

  const setProgress = (t: number) => {
    progress = THREE.MathUtils.clamp(t, 0, 1);
  };

  const update = (elapsedSeconds = 0) => {
    if (!config.manualElevation) {
      config.elevation = THREE.MathUtils.lerp(config.elevationStart, config.elevationEnd, progress);
    }

    sunDirectionFrom(config.elevation, config.azimuth, sunDirection);
    sunPosition.copy(sunDirection);

    const uniforms = sky.material.uniforms;
    uniforms.turbidity.value = config.turbidity;
    uniforms.rayleigh.value = config.rayleigh;
    uniforms.mieCoefficient.value = config.mieCoefficient;
    uniforms.mieDirectionalG.value = config.mieDirectionalG;
    uniforms.cloudCoverage.value = config.cloudCoverage;
    uniforms.cloudDensity.value = config.cloudDensity;
    uniforms.cloudScale.value = config.cloudScale;
    uniforms.cloudSpeed.value = config.cloudSpeed;
    uniforms.cloudElevation.value = config.cloudElevation;
    uniforms.showSunDisc.value = config.showSunDisc ? 1 : 0;
    uniforms.time.value = elapsedSeconds;
    if (uniforms.skyLuminance) uniforms.skyLuminance.value = config.luminance;
    sky.position.copy(camera.position);

    params.turbidity = config.turbidity;
    params.rayleigh = config.rayleigh;
    params.mieCoefficient = config.mieCoefficient;
    params.mieDirectionalG = config.mieDirectionalG;
    updateAtmosphere(atmosphere, sunDirection, params);

    // --- the key light ------------------------------------------------- //
    sun.position.copy(sunDirection).multiplyScalar(sunDistance);
    sunExtinction(atmosphere, sunColor);
    const sunLuminance = 0.2126 * sunColor.r + 0.7152 * sunColor.g + 0.0722 * sunColor.b;
    // Hue from the extinction term, strength from its luminance.
    // Normalising the colour to its brightest channel stops the falloff
    // being applied twice - otherwise the light dims twice over and never
    // actually warms.
    const peak = Math.max(sunColor.r, sunColor.g, sunColor.b, 1e-4);
    sun.color.setRGB(
      sunColor.r / peak,
      sunColor.g / peak,
      sunColor.b / peak,
      THREE.LinearSRGBColorSpace,
    );
    sun.intensity = config.sunIntensity * (sunLuminance / ZENITH_SUN_LUMINANCE);

    if (shadowsOn) {
      sun.shadow.intensity = config.shadowIntensity;
      sun.shadow.bias = config.shadowBias;
      sun.shadow.normalBias = config.shadowNormalBias;

      if (config.shadowRadius !== lastShadowRadius) {
        const shadowCamera = sun.shadow.camera;
        shadowCamera.left = -config.shadowRadius;
        shadowCamera.right = config.shadowRadius;
        shadowCamera.top = config.shadowRadius;
        shadowCamera.bottom = -config.shadowRadius;
        shadowCamera.updateProjectionMatrix();
        lastShadowRadius = config.shadowRadius;
        lastShadowElevation = Number.NaN;
      }

      // Negated rather than written as `>=` so the NaN first frame takes
      // this branch instead of skipping it.
      if (!(Math.abs(config.elevation - lastShadowElevation) < config.shadowStepDeg)) {
        sun.shadow.needsUpdate = true;
        lastShadowElevation = config.elevation;
      }
    }

    // --- the fill ------------------------------------------------------ //
    // Sampled between straight up and the sun rather than at either: the
    // zenith alone is a saturated blue that paints the rock blue, and the
    // sun alone is a warm cast with none of the sky in it. This is roughly
    // what a mountainside actually sees.
    sampleDirection.set(0, 0.7, 0).addScaledVector(sunDirection, 0.3).normalize();
    skyRadiance(atmosphere, sampleDirection, params, ambientColor);
    const ambientPeak = Math.max(ambientColor.r, ambientColor.g, ambientColor.b, 1e-4);
    ambient.color.setRGB(
      ambientColor.r / ambientPeak,
      ambientColor.g / ambientPeak,
      ambientColor.b / ambientPeak,
      THREE.LinearSRGBColorSpace,
    );
    ambient.intensity = config.ambientIntensity;

    // --- the fog ------------------------------------------------------- //
    if (config.fogFollowsSky && scene.fog instanceof THREE.FogExp2) {
      // Along the bearing the camera is facing, lifted off the horizon by
      // fogSkyPitch. The bearing matters because the horizon is warm near
      // the sun and cool away from it, and the massif has to fade into
      // whichever of those is actually behind it; the lift matters for the
      // reason given on fogSkyPitch.
      camera.getWorldDirection(viewDirection);
      viewDirection.y = 0;
      if (viewDirection.lengthSq() < 1e-6) viewDirection.set(0, 0, 1);
      const pitch = THREE.MathUtils.degToRad(config.fogSkyPitch);
      viewDirection.normalize().multiplyScalar(Math.cos(pitch));
      viewDirection.y = Math.sin(pitch);
      skyRadiance(atmosphere, viewDirection, params, fogColor);
      const scale = config.luminance * config.fogBrightness;
      scene.fog.color.setRGB(
        fogColor.r * scale,
        fogColor.g * scale,
        fogColor.b * scale,
        THREE.LinearSRGBColorSpace,
      );
      scene.fog.density = config.fogDensity;
    }
  };

  const dispose = () => {
    scene.remove(sky, sun, sun.target, ambient);
    sky.geometry.dispose();
    sky.material.dispose();
    sun.dispose();
    ambient.dispose();
  };

  return { config, sky, sun, ambient, sunDirection, setProgress, update, dispose };
}
