import * as THREE from "three";
import type { TerrainSampler } from "./terrain-sampler";

/**
 * Summit and milestone flags.
 *
 * These replace the waypoint rings. A ring had to be billboarded to read as
 * a circle and could only announce a milestone by changing colour; a flag
 * announces one by *arriving* - it shoots up out of the mountain, the cloth
 * snaps open behind it, and from then on it keeps moving in the wind. That
 * motion is the point: the rings were the only static thing in a scene whose
 * whole subject is a climb in progress.
 *
 * Two things here are worth knowing before changing anything:
 *
 * 1. The cloth is deformed in the vertex shader, not on the CPU and not by
 *    an imported animation. A baked cloth sim would have to ship as
 *    vertex-animated geometry (or bones) for five flags and would still
 *    loop; a wave function costs one Standard material with an injected
 *    chunk, runs at whatever framerate the page gets, and can be gusted on
 *    demand - which is exactly what the pop needs. The shading normal is
 *    rebuilt from the same function by finite difference, so the lit side of
 *    a fold is the side actually facing the sun rather than the flat plane's.
 *
 * 2. The pop is a spring in real time, not a curve in scroll position.
 *    Scroll progress only sets the spring's target (planted / not planted).
 *    Driving the pop from progress directly - as the old summit flash did -
 *    means the animation plays at whatever speed the visitor happens to be
 *    scrolling, so a fast flick skips it entirely and a slow drag stretches
 *    it into nothing. A spring always takes the same ~0.6s, and because it
 *    is a spring it also handles being un-popped by a scrub back down.
 *
 * Disposal is not handled here: every mesh below lives in the scene graph,
 * and initScene's dispose() already traverses it.
 */

/** Spring constants for the pop. zeta ~0.48 - overshoots ~19%, settles in ~0.6s. */
const POP_STIFFNESS = 210;
const POP_DAMPING = 14;
/** Fixed integration step, so a dropped frame cannot blow the spring up. */
const POP_STEP = 1 / 120;

/** Cloth tessellation. The wave is low-frequency; this is plenty to carry it. */
const CLOTH_SEGMENTS_X = 24;
const CLOTH_SEGMENTS_Y = 14;

export interface FlagOptions {
  /** Ground point the pole is planted in - the base of the pole, not the cloth. */
  base: THREE.Vector3;
  poleHeight: number;
  clothWidth: number;
  clothHeight: number;
  /** Cloth colour. Red, and the only red in the scene - see --flag in tokens.css. */
  clothColor: THREE.Color;
  /** Colour the cloth glows as it snaps open. */
  clothLitColor: THREE.Color;
  /** Pole and finial - non-emissive hardware. */
  poleColor: THREE.Color;
  /** Offset into the wind so a row of flags does not ripple in lockstep. */
  phase: number;
}

export interface Flag {
  object: THREE.Group;
  /** Sets the spring's target. Idempotent - safe to call every frame. */
  setPlanted: (planted: boolean) => void;
  /** Advances the wind and the pop spring, and turns the cloth to the camera. */
  update: (camera: THREE.Camera, dt: number) => void;
}

interface ClothUniforms {
  uTime: { value: number };
  uWind: { value: number };
  uUnfurl: { value: number };
  uPhase: { value: number };
  uClothSize: { value: THREE.Vector2 };
}

/**
 * The wave itself, as GLSL. Written as a function of a point on the flat
 * cloth so the same call can produce the vertex position and - evaluated
 * twice more, a fraction of a unit away - the surface normal that goes with
 * it.
 *
 * Amplitude is multiplied by span^2, which is what pins the cloth to the
 * hoist: at the pole the term is zero however hard the wind blows, and it
 * opens up quadratically toward the fly edge. Everything scales with the
 * cloth's own height, so the same numbers serve the small milestone flags
 * and the large summit one.
 */
const CLOTH_CHUNK = /* glsl */ `
uniform float uTime;
uniform float uWind;
uniform float uUnfurl;
uniform float uPhase;
uniform vec2 uClothSize;

vec3 npdClothPoint( vec2 p ) {
  // p.x runs 0..width from the hoist; p.y runs -height..0 down from the top.
  float u = clamp( p.x / uClothSize.x, 0.0, 1.0 );
  float span = u * uUnfurl;
  float amp = span * span * uWind * uClothSize.y;

  float t = uTime + uPhase;
  float phase = t * 5.5 - span * 8.0;

  float z = sin( phase ) * 0.42;
  z += sin( phase * 1.63 + p.y * 1.9 ) * 0.22;
  z += sin( t * 12.0 + p.y * 4.5 ) * 0.10 * span;
  z *= amp;

  // A flag in the wind rides up, and reads shorter across than it is flat.
  float lift = amp * 0.18 * ( 0.6 + 0.4 * sin( phase * 0.8 ) );
  float x = span * uClothSize.x * ( 1.0 - 0.10 * amp / max( uClothSize.y, 1e-4 ) );

  return vec3( x, p.y + lift, z );
}
`;

function createCloth(o: FlagOptions): {
  mesh: THREE.Mesh;
  uniforms: ClothUniforms;
  material: THREE.MeshStandardMaterial;
} {
  const geometry = new THREE.PlaneGeometry(
    o.clothWidth,
    o.clothHeight,
    CLOTH_SEGMENTS_X,
    CLOTH_SEGMENTS_Y,
  );
  // Hoist edge to x=0, top edge to y=0: the shader's whole coordinate system
  // is "distance from the pole, distance below the truck", and a centred
  // plane would put the pinned corner in the middle of the cloth.
  geometry.translate(o.clothWidth / 2, -o.clothHeight / 2, 0);

  const uniforms: ClothUniforms = {
    uTime: { value: 0 },
    uWind: { value: 1 },
    uUnfurl: { value: 0 },
    uPhase: { value: o.phase },
    uClothSize: { value: new THREE.Vector2(o.clothWidth, o.clothHeight) },
  };

  const material = new THREE.MeshStandardMaterial({
    color: o.clothColor,
    emissive: o.clothLitColor,
    emissiveIntensity: 0.25,
    roughness: 0.78,
    metalness: 0,
    side: THREE.DoubleSide,
  });

  material.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);

    shader.vertexShader = shader.vertexShader
      .replace("#include <common>", `#include <common>\n${CLOTH_CHUNK}`)
      .replace(
        "#include <beginnormal_vertex>",
        /* glsl */ `
        vec3 npdCloth = npdClothPoint( position.xy );
        vec3 npdClothDx = npdClothPoint( position.xy + vec2( 0.05, 0.0 ) ) - npdCloth;
        vec3 npdClothDy = npdClothPoint( position.xy + vec2( 0.0, 0.05 ) ) - npdCloth;
        vec3 npdClothN = cross( npdClothDx, npdClothDy );
        // Furled flat against the pole the two tangents collapse and the
        // cross product is zero, which would normalize to NaN and take the
        // whole mesh with it. The plane's own normal is the answer there.
        vec3 objectNormal = length( npdClothN ) > 1e-6 ? normalize( npdClothN ) : normal;
        `,
      )
      .replace("#include <begin_vertex>", "vec3 transformed = npdCloth;");
  };
  // Explicit, so this material can never share a compiled program with the
  // scene's other Standard materials (the pole below is one of them).
  material.customProgramCacheKey = () => "npd-flag-cloth";

  const mesh = new THREE.Mesh(geometry, material);
  // The wave pushes vertices well outside the flat plane's bounds, and the
  // whole flag is a handful of triangles - culling it against a stale box is
  // all downside.
  mesh.frustumCulled = false;

  return { mesh, uniforms, material };
}

function shortestAngle(from: number, to: number): number {
  let delta = (to - from) % (Math.PI * 2);
  if (delta > Math.PI) delta -= Math.PI * 2;
  if (delta < -Math.PI) delta += Math.PI * 2;
  return delta;
}

/**
 * One flag: pole, finial, cloth, and the spring that plants it.
 *
 * The pole is plumb rather than aligned to the surface normal - flags are
 * plumb - and the group is scaled up the Y axis from the base, so a pop
 * reads as the flag being driven into the ground rather than a whole object
 * fading in.
 */
export function createFlag(o: FlagOptions): Flag {
  const object = new THREE.Group();
  object.position.copy(o.base);

  // Cloth and hardware sit under a yaw group, so turning the flag to face
  // the camera does not also rotate the pop scale that lives on `object`.
  const yaw = new THREE.Group();
  object.add(yaw);

  const poleRadius = Math.max(0.16, o.clothHeight * 0.06);
  const poleMaterial = new THREE.MeshStandardMaterial({
    color: o.poleColor,
    roughness: 0.6,
    metalness: 0.2,
  });
  const pole = new THREE.Mesh(
    new THREE.CylinderGeometry(poleRadius * 0.72, poleRadius, o.poleHeight, 8),
    poleMaterial,
  );
  pole.position.y = o.poleHeight / 2;
  yaw.add(pole);

  const finial = new THREE.Mesh(new THREE.SphereGeometry(poleRadius * 1.5, 10, 8), poleMaterial);
  finial.position.y = o.poleHeight;
  yaw.add(finial);

  const { mesh: cloth, uniforms, material: clothMaterial } = createCloth(o);
  cloth.position.set(poleRadius * 0.6, o.poleHeight - poleRadius * 1.6, 0);
  yaw.add(cloth);

  object.visible = false;
  object.scale.y = 0;

  let target = 0;
  let value = 0;
  let velocity = 0;
  let time = 0;
  // Damped, not snapped: the camera dollies sideways across the climb, and a
  // yaw that tracked it exactly would turn every flag in lockstep with the
  // scroll, which reads as the mountain rotating rather than the camera
  // moving.
  let yawAngle: number | null = null;

  const setPlanted = (planted: boolean) => {
    target = planted ? 1 : 0;
  };

  const toCamera = new THREE.Vector3();
  const worldPosition = new THREE.Vector3();

  const update = (camera: THREE.Camera, dt: number) => {
    // Clamped: a backgrounded tab hands back a delta of several seconds, and
    // a spring integrated over that in one step explodes.
    const step = Math.min(Math.max(dt, 0), 0.05);
    time += step;

    let remaining = step;
    while (remaining > 0) {
      const h = Math.min(POP_STEP, remaining);
      velocity += (target - value) * POP_STIFFNESS * h - velocity * POP_DAMPING * h;
      value += velocity * h;
      remaining -= h;
    }
    if (value < 0) {
      value = 0;
      velocity = Math.max(velocity, 0);
    }

    object.visible = value > 0.002;
    if (!object.visible) return;

    object.scale.y = value;

    // The cloth rolls out once the pole is most of the way up, so the two
    // halves of the pop read as one gesture instead of happening at once.
    const unfurl = THREE.MathUtils.smoothstep(value, 0.25, 1);
    // Everything below is driven off the spring's own velocity: the flag
    // gusts hardest and glows brightest at the instant it snaps out, with no
    // second timeline to keep in sync with the first.
    const snap = THREE.MathUtils.clamp(Math.abs(velocity) * 0.22, 0, 1.8);

    uniforms.uTime.value = time;
    uniforms.uUnfurl.value = unfurl;
    uniforms.uWind.value = 1 + snap * 1.4;
    clothMaterial.emissiveIntensity = 0.25 + snap * 1.6;

    object.getWorldPosition(worldPosition);
    toCamera.subVectors(camera.position, worldPosition);
    // atan2 alone turns local +Z toward the lens, and the cloth's face
    // normal is its ±Z - so this is the flag broadside, flying across the
    // frame. It used to carry a further +90 degrees, which turned the same
    // cloth edge-on and streamed it straight away from the viewer: a flag
    // seen along its own length, which at this distance is a red stripe.
    // The drift term is a slow change of wind direction, and it is what
    // keeps the result from reading as a billboard.
    const facing = Math.atan2(toCamera.x, toCamera.z) + Math.sin(time * 0.31 + o.phase) * 0.14;
    yawAngle =
      yawAngle === null
        ? facing
        : yawAngle + shortestAngle(yawAngle, facing) * Math.min(1, step * 2.5);
    yaw.rotation.y = yawAngle;
  };

  return { object, setPlanted, update };
}

export interface MilestoneFlagOptions {
  /** anchorPoints from createTrail - the trail line's own world positions. */
  anchorPoints: THREE.Vector3[];
  /** Height authority, used to find the ground under each anchor. */
  sampler: TerrainSampler;
  clothColor: THREE.Color;
  clothLitColor: THREE.Color;
  poleColor: THREE.Color;
  /** How far the cloth hangs above the trail line it marks. */
  clearance?: number;
  clothWidth?: number;
  clothHeight?: number;
}

export interface MilestoneFlags {
  object: THREE.Group;
  update: (camera: THREE.Camera, dt: number) => void;
  /** Plants or pulls flag `index`. Driven from the trail's own progress. */
  setPlanted: (index: number, planted: boolean) => void;
}

/**
 * The milestone flags, one per waypoint.
 *
 * Each pole is planted in the surface directly *below* its trail anchor and
 * made tall enough to carry the cloth back up over the line. Going straight
 * down in world space from the anchor - rather than re-deriving a surface
 * point from the waypoint's original x/z - is what keeps a flag over its own
 * point of the trail on a slope: the trail is offset along the surface
 * normal, so on a gradient its anchor is displaced sideways as well as up,
 * and a pole re-projected from the pre-offset coordinates would stand
 * visibly off the line.
 */
export function buildMilestoneFlags(o: MilestoneFlagOptions): MilestoneFlags {
  const object = new THREE.Group();
  const clearance = o.clearance ?? 7;
  const clothWidth = o.clothWidth ?? 6;
  const clothHeight = o.clothHeight ?? 3.8;

  const flags = o.anchorPoints.map((anchor, i) => {
    const ground = o.sampler.heightAt(anchor.x, anchor.z);
    const flag = createFlag({
      base: new THREE.Vector3(anchor.x, ground, anchor.z),
      // The gap the sampler reports under the anchor, plus the clearance the
      // cloth needs above it - so the pole always reaches the line, however
      // steep the ground under that waypoint is.
      poleHeight: anchor.y - ground + clearance,
      clothWidth,
      clothHeight,
      clothColor: o.clothColor,
      clothLitColor: o.clothLitColor,
      poleColor: o.poleColor,
      phase: i * 1.7,
    });
    object.add(flag.object);
    return flag;
  });

  return {
    object,
    update: (camera, dt) => {
      for (const flag of flags) flag.update(camera, dt);
    },
    setPlanted: (index, planted) => flags[index]?.setPlanted(planted),
  };
}
