import * as THREE from "three";
import { Line2 } from "three/examples/jsm/lines/Line2.js";
import { LineGeometry } from "three/examples/jsm/lines/LineGeometry.js";
import { LineMaterial } from "three/examples/jsm/lines/LineMaterial.js";
import type { TerrainSampler } from "./terrain-sampler";
import { buildMilestoneFlags, createFlag } from "./flags";

const SAMPLE_COUNT = 600;

export interface TrailOptions {
  worldSize: number;
  maxHeight: number;
  /**
   * The terrain's one height authority. Every Y in this module comes from
   * here - there is no second lookup, no raycast, no constant.
   */
  sampler: TerrainSampler;
  brandColor: THREE.Color;
  brandLitColor: THREE.Color;
  /** Bright colour for the drawing head's short tip. */
  tipColor: THREE.Color;
  /** Structural colour for beacon/pole geometry (non-emissive parts). */
  structureColor: THREE.Color;
  /** Cloth colour for every flag - the milestones and the summit alike. */
  flagColor: THREE.Color;
  /** Colour the cloth glows as it snaps open. */
  flagLitColor: THREE.Color;
  /** Target perpendicular clearance, in world units, kept between the trail and the local terrain surface. */
  surfaceOffset?: number;
  linewidth?: number;
}

// Each leg's angular sweep grows as radius shrinks, so arc length (and
// therefore how much of the 0..1 progress range) stays roughly balanced
// across legs instead of the wide base leg dominating the whole climb.
// Sweep direction alternates leg to leg for real switchback hairpins.
//
// These are tighter than the route the page shipped with, which wrapped 183
// degrees of the massif and swung out to 0.8 of its half width. That one was
// cut for a 16:9 frame and came apart on a phone held upright: the camera has
// only so much lens and standoff with which to win back the width a narrow
// frame loses (fitToViewport in camera-rig.ts), and once both are spent the
// middle of the climb - the part anyone is actually watching the head draw -
// ran 15-20% beyond the frame edge. What fixed it was a narrower mountain
// path rather than a wider shot of the same one: the same five anchors and
// the same alternating hairpins, with every angle pulled to 0.62 of its
// spread about the route's own mean bearing and every radius to 0.88.
//
// It is the only route, landscape included, because the tighter line turned
// out to read better in every frame rather than merely to fit in the narrow
// one. It wraps 114 degrees instead of 183 and runs 513 world units instead
// of 877, so it climbs more directly; none of it passes behind the summit
// from the bearing the camera stands on, where the old route hid about 12% of
// itself; and at 16:9 the whole climb including the trailhead now sits inside
// the frame, where the old one started about half a frame outside it. The
// price is width: at 16:9 the switchbacks use about 55% of the half frame
// where the old ones used 87%.
//
// Radius 0.7 at the base rather than something tighter still is what keeps
// the trailhead at the foot of the mountain. The massif's cone falloff (see
// heightmap.ts) puts 0.7 at about 6% of peak height, where 0.56 - which
// framed a little better again - would have started the climb a sixth of the
// way up its own mountain.
const LEG_ANGLES = [-1.97, -0.98, -2.35, -0.73, -0.36];
const LEG_RADII = [0.7, 0.48, 0.28, 0.11, 0];

export interface TrailWaypoints {
  base: THREE.Vector3;
  wp1: THREE.Vector3;
  wp2: THREE.Vector3;
  wp3: THREE.Vector3;
  summit: THREE.Vector3;
}

export interface TrailResult {
  /** Line + milestone and summit flags, ready to add to the scene. */
  group: THREE.Group;
  waypoints: TrailWaypoints;
  /** Normalised arc-length position of [base, wp1, wp2, wp3, summit] along the trail, 0..1. */
  waypointProgress: [number, number, number, number, number];
  /** Full spiral control-point chain (anchors + switchback mids), before it is resampled into the line. */
  controlPoints: THREE.Vector3[];
  /**
   * The rendered line's own world position at [base, wp1, wp2, wp3, summit].
   * Read straight out of the sample array rather than re-derived from the
   * sampler, so anything hung off a waypoint is anchored to the trail itself.
   */
  anchorPoints: THREE.Vector3[];
  /**
   * Advances every flag's wind and pop spring and turns them to the camera.
   * Call once per frame with the frame's delta in seconds - the flags animate
   * in real time, not in scroll position, so they need a clock of their own.
   */
  updateFlags: (camera: THREE.Camera, dt: number) => void;
  /** Drives the draw-on reveal and plants each flag. 0 = nothing climbed, 1 = summit reached. */
  setProgress: (t: number) => void;
}

function polarPoint(
  angle: number,
  radiusFrac: number,
  halfWidth: number,
  sampler: TerrainSampler,
  clearance: number,
): THREE.Vector3 {
  const r = radiusFrac * halfWidth;
  return sampler.pointOnSurface(Math.cos(angle) * r, Math.sin(angle) * r, clearance);
}

/** Interpolates a switchback leg's angle/radius with a few mid points so the
 * spline actually arcs around the mountain's flank instead of chording
 * straight through it between two widely-spaced anchors. */
function buildLeg(
  fromAngle: number,
  toAngle: number,
  fromRadius: number,
  toRadius: number,
  halfWidth: number,
  sampler: TerrainSampler,
  clearance: number,
  midCount: number,
): THREE.Vector3[] {
  const mids: THREE.Vector3[] = [];
  for (let i = 1; i <= midCount; i++) {
    const f = i / (midCount + 1);
    const angle = THREE.MathUtils.lerp(fromAngle, toAngle, f);
    const radius = THREE.MathUtils.lerp(fromRadius, toRadius, f);
    mids.push(polarPoint(angle, radius, halfWidth, sampler, clearance));
  }
  return mids;
}

/** Builds the 5 named anchors plus switchback mid points that make the
 * ascent wrap partway around the mountain, alternating sweep direction leg
 * to leg like a real switchback trail. Returns the flat control-point chain
 * and the index of each named anchor within it. */
function buildSpiral(
  halfWidth: number,
  sampler: TerrainSampler,
  clearance: number,
) {
  const angles = LEG_ANGLES;
  const radii = LEG_RADII;

  const controlPoints: THREE.Vector3[] = [];
  const anchorIndices: number[] = [];

  const anchorAt = (i: number) => polarPoint(angles[i], radii[i], halfWidth, sampler, clearance);

  const legMids = [3, 3, 2, 2];

  for (let i = 0; i < angles.length; i++) {
    anchorIndices.push(controlPoints.length);
    controlPoints.push(anchorAt(i));
    if (i < angles.length - 1) {
      controlPoints.push(
        ...buildLeg(
          angles[i],
          angles[i + 1],
          radii[i],
          radii[i + 1],
          halfWidth,
          sampler,
          clearance,
          legMids[i],
        ),
      );
    }
  }

  return { controlPoints, anchorIndices };
}

const MIN_SAMPLES_PER_LEG = 60;

/** Rough arc length of a leg, used only to weight how many of the dense
 * samples each leg gets - doesn't need to be exact. */
function legWeight(legIndex: number): number {
  const angleSweep = Math.abs(LEG_ANGLES[legIndex + 1] - LEG_ANGLES[legIndex]);
  const avgRadius = (LEG_RADII[legIndex] + LEG_RADII[legIndex + 1]) / 2;
  const radialDelta = Math.abs(LEG_RADII[legIndex + 1] - LEG_RADII[legIndex]);
  return avgRadius * angleSweep + radialDelta;
}

/**
 * Densely samples the trail by interpolating angle and radius *separately*
 * per leg, then converting to XZ - not by running a Cartesian CatmullRom
 * through the sparse control points and resampling that. A 3D spline through
 * Cartesian points can overshoot near a sharp direction change (exactly what
 * every switchback corner is), and an overshoot toward a smaller radius
 * swings the path closer to the summit than either neighbouring anchor
 * intended - straight at taller terrain neither anchor accounted for. Since
 * angle and radius are each interpolated independently and boundedly between
 * their own two leg endpoints, the radius can never dip past what the route
 * actually intends, no matter how sharp the turn.
 */
function buildTrailSamples(
  halfWidth: number,
  sampler: TerrainSampler,
  clearance: number,
  totalSamples: number,
): { points: THREE.Vector3[]; anchorIndices: number[] } {
  const legCount = LEG_ANGLES.length - 1;
  const weights = Array.from({ length: legCount }, (_, i) => legWeight(i));
  const totalWeight = weights.reduce((a, b) => a + b, 0);
  const remaining = Math.max(0, totalSamples - MIN_SAMPLES_PER_LEG * legCount);
  const legSampleCounts = weights.map((w) =>
    Math.max(2, MIN_SAMPLES_PER_LEG + Math.round((w / totalWeight) * remaining)),
  );

  const points: THREE.Vector3[] = [];
  const anchorIndices: number[] = [0];

  for (let leg = 0; leg < legCount; leg++) {
    const count = legSampleCounts[leg];
    const fromAngle = LEG_ANGLES[leg];
    const toAngle = LEG_ANGLES[leg + 1];
    const fromRadius = LEG_RADII[leg];
    const toRadius = LEG_RADII[leg + 1];
    // Leg 0 emits both endpoints; later legs start at 1 since their first
    // sample is identical to the previous leg's last (the shared anchor).
    const start = leg === 0 ? 0 : 1;
    for (let s = start; s < count; s++) {
      const f = s / (count - 1);
      const angle = THREE.MathUtils.lerp(fromAngle, toAngle, f);
      const radiusFrac = THREE.MathUtils.lerp(fromRadius, toRadius, f);
      const x = Math.cos(angle) * radiusFrac * halfWidth;
      const z = Math.sin(angle) * radiusFrac * halfWidth;
      points.push(sampler.pointOnSurface(x, z, clearance));
    }
    anchorIndices.push(points.length - 1);
  }

  return { points, anchorIndices };
}

function setSegmentScalarAttribute(
  geometry: LineGeometry,
  startName: string,
  endName: string,
  chainValues: Float32Array,
): void {
  const segmentCount = chainValues.length - 1;
  const paired = new Float32Array(segmentCount * 2);
  for (let i = 0; i < segmentCount; i++) {
    paired[i * 2] = chainValues[i];
    paired[i * 2 + 1] = chainValues[i + 1];
  }
  const buffer = new THREE.InstancedInterleavedBuffer(paired, 2, 1);
  geometry.setAttribute(startName, new THREE.InterleavedBufferAttribute(buffer, 1, 0));
  geometry.setAttribute(endName, new THREE.InterleavedBufferAttribute(buffer, 1, 1));
}

function createTrailLine(
  halfWidth: number,
  options: TrailOptions,
): { line: Line2; points: THREE.Vector3[]; anchorIndices: number[]; cumulative: Float32Array } {
  const clearance = options.surfaceOffset ?? 1;
  const { points, anchorIndices } = buildTrailSamples(
    halfWidth,
    options.sampler,
    clearance,
    SAMPLE_COUNT,
  );

  const cumulative = new Float32Array(points.length);
  let total = 0;
  for (let i = 1; i < points.length; i++) {
    total += points[i].distanceTo(points[i - 1]);
    cumulative[i] = total;
  }
  if (total > 0) {
    for (let i = 0; i < cumulative.length; i++) cumulative[i] /= total;
  }

  const flatPositions = new Float32Array(points.length * 3);
  for (let i = 0; i < points.length; i++) {
    flatPositions[i * 3] = points[i].x;
    flatPositions[i * 3 + 1] = points[i].y;
    flatPositions[i * 3 + 2] = points[i].z;
  }

  const geometry = new LineGeometry();
  geometry.setPositions(flatPositions);
  setSegmentScalarAttribute(geometry, "instanceArcStart", "instanceArcEnd", cumulative);

  const uniforms = {
    uProgress: { value: 0 },
    uColorBase: { value: options.brandColor },
    // Boosted past 1.0 rather than left at the raw token value: the renderer's
    // ACES tone mapping (see renderer.ts) blows out over-bright colour toward
    // white, which is what reads as "glow" here. Actual additive GL blending
    // was the first attempt, but Line2 draws every one of the 600 vertices as
    // its own quad with an overlapping round join, and additive blending
    // doubles up that overlap into a visible bright dot at each one - this
    // gets the same hot, glowing look through tone mapping instead, with
    // ordinary (non-additive) blending so the overlaps stay invisible.
    uColorLit: { value: options.brandLitColor.clone().multiplyScalar(1.6) },
    uColorTip: { value: options.tipColor.clone().multiplyScalar(2.4) },
    uTipLength: { value: 0.02 },
  };

  const material = new LineMaterial({
    linewidth: options.linewidth ?? 7,
    worldUnits: false,
    transparent: true,
    depthWrite: false,
    blending: THREE.NormalBlending,
  });

  material.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);

    shader.vertexShader = shader.vertexShader
      .replace(
        "uniform vec2 resolution;",
        `uniform vec2 resolution;
        attribute float instanceArcStart;
        attribute float instanceArcEnd;
        varying float vArcLength;`,
      )
      .replace(
        "void main() {",
        `void main() {

        vArcLength = ( position.y < 0.5 ) ? instanceArcStart : instanceArcEnd;`,
      );

    shader.fragmentShader = shader.fragmentShader
      .replace(
        "uniform float linewidth;",
        `uniform float linewidth;
        uniform float uProgress;
        uniform vec3 uColorBase;
        uniform vec3 uColorLit;
        uniform vec3 uColorTip;
        uniform float uTipLength;
        varying float vArcLength;`,
      )
      .replace(
        "void main() {",
        `void main() {

        if ( vArcLength > uProgress ) discard;`,
      )
      .replace(
        "gl_FragColor = vec4( diffuseColor.rgb, alpha );",
        `float trailT = clamp( vArcLength / max( uProgress, 1e-4 ), 0.0, 1.0 );
        vec3 shaftColor = mix( uColorBase, uColorLit, smoothstep( 0.0, 1.0, trailT ) );
        float headDist = uProgress - vArcLength;
        float tipMask = 1.0 - smoothstep( 0.0, uTipLength, headDist );
        vec3 trailFinalColor = mix( shaftColor, uColorTip, tipMask );
        gl_FragColor = vec4( trailFinalColor, alpha );`,
      );
  };
  material.customProgramCacheKey = () => "trail-drawon";
  material.userData.trailUniforms = uniforms;

  const line = new Line2(geometry, material);
  line.computeLineDistances();
  line.frustumCulled = false;

  return { line, points, anchorIndices, cumulative };
}

/** Cloth size for the two milestone flags, in world units. */
const MILESTONE_CLOTH = { width: 8, height: 5 };
/**
 * The summit flag is the one the whole page climbs to, and the camera is at
 * its longest lens by the time it arrives - so it is drawn half again as big
 * as a milestone rather than the same size.
 */
const SUMMIT_CLOTH = { width: 12, height: 7.4 };
/** How far each cloth hangs above the trail line it marks. */
const MILESTONE_CLEARANCE = 8;
const SUMMIT_CLEARANCE = 13;

export function createTrail(options: TrailOptions): TrailResult {
  const halfWidth = options.worldSize / 2;
  const clearance = options.surfaceOffset ?? 9;

  const { controlPoints, anchorIndices } = buildSpiral(halfWidth, options.sampler, clearance);

  const {
    line,
    points: linePoints,
    anchorIndices: lineAnchorIndices,
    cumulative,
  } = createTrailLine(halfWidth, options);

  // Exact now - these are the literal sample indices where each named
  // anchor falls in the rendered line's own point chain, not an
  // approximation carried over from a differently-parameterized curve.
  const waypointProgress = lineAnchorIndices.map((idx) => cumulative[idx]) as [
    number,
    number,
    number,
    number,
    number,
  ];

  const waypoints: TrailWaypoints = {
    base: controlPoints[anchorIndices[0]],
    wp1: controlPoints[anchorIndices[1]],
    wp2: controlPoints[anchorIndices[2]],
    wp3: controlPoints[anchorIndices[3]],
    summit: controlPoints[anchorIndices[4]],
  };

  const group = new THREE.Group();
  group.add(line);

  // The exact vertices the line was built from, not a second lookup: these
  // are the positions the rings hang above, so they track the trail on a
  // flank where a re-projected surface point would drift off it sideways.
  const anchorPoints = lineAnchorIndices.map((i) => linePoints[i].clone());

  // [wp1, wp2] - the base carries nothing (nobody plants a flag where they
  // set off from) and the summit gets its own, larger one below. wp3 is
  // deliberately not flagged: it sits at 94% of the route, so its flag popped
  // a beat before the summit's and read as a second, smaller summit flag
  // rather than as a milestone on the way up.
  const milestones = buildMilestoneFlags({
    anchorPoints: anchorPoints.slice(1, 3),
    sampler: options.sampler,
    clothColor: options.flagColor,
    clothLitColor: options.flagLitColor,
    poleColor: options.structureColor,
    clearance: MILESTONE_CLEARANCE,
    clothWidth: MILESTONE_CLOTH.width,
    clothHeight: MILESTONE_CLOTH.height,
  });
  group.add(milestones.object);

  // Pole height is the real vertical gap the sampler reports under the
  // trail's summit point, not the clearance constant: clearance is measured
  // along the normal, so on any slope the vertical distance is larger. Taking
  // the difference means the pole tip lands on the line instead of short of it.
  const summitAnchor = anchorPoints[anchorPoints.length - 1];
  const summitGround = options.sampler.heightAt(summitAnchor.x, summitAnchor.z);
  const summitFlag = createFlag({
    base: new THREE.Vector3(summitAnchor.x, summitGround, summitAnchor.z),
    poleHeight: summitAnchor.y - summitGround + SUMMIT_CLEARANCE,
    clothWidth: SUMMIT_CLOTH.width,
    clothHeight: SUMMIT_CLOTH.height,
    clothColor: options.flagColor,
    clothLitColor: options.flagLitColor,
    poleColor: options.structureColor,
    // Deliberately out of phase with both milestone flags (0, 1.7), so the
    // summit's cloth is never mirroring one further down the mountain.
    phase: 5.2,
  });
  group.add(summitFlag.object);

  const trailUniforms = (line.material as LineMaterial).userData.trailUniforms as {
    uProgress: { value: number };
  };

  // A flag is planted or it is not - there is no half-planted state for
  // progress to interpolate. Everything continuous about the pop lives in
  // the flag's own spring, which is why these are plain thresholds.
  const setProgress = (t: number) => {
    const clamped = THREE.MathUtils.clamp(t, 0, 1);
    trailUniforms.uProgress.value = clamped;

    for (let i = 1; i <= 2; i++) {
      milestones.setPlanted(i - 1, clamped >= waypointProgress[i]);
    }

    summitFlag.setPlanted(clamped >= waypointProgress[4]);
  };
  setProgress(0);

  const updateFlags = (camera: THREE.Camera, dt: number) => {
    milestones.update(camera, dt);
    summitFlag.update(camera, dt);
  };

  return {
    group,
    waypoints,
    waypointProgress,
    controlPoints,
    anchorPoints,
    updateFlags,
    setProgress,
  };
}
