import * as THREE from "three";
import { PARTICLE_FOG, type ParticleFogConfig } from "./particle-fog.config";

/**
 * Drifting banks of mist over the valley: one InstancedMesh of camera-
 * facing cards, one draw call, no CPU work per frame.
 *
 * This is the cheap half of volumetric fog. The scene already has the
 * other half - an exponential distance haze owned by the sky rig - and
 * what that cannot do is have *structure*: it is a function of depth
 * alone, so it greys the distance evenly and never pools, never drifts,
 * never lets a ridge stand out of it. These cards are that structure.
 *
 * Everything moves in the vertex shader. The drift, the wrap at the domain
 * edge, the bob, the spin and all three fades are computed from a single
 * uTime, so the rig's per-frame work is assigning a handful of uniforms -
 * there is no particle array on the CPU and nothing is re-uploaded. That
 * matters more than it looks: a few hundred billboards updated in
 * JavaScript and pushed to the GPU every frame is a classic way to spend
 * a millisecond of main thread on a scene that is otherwise free.
 *
 * WHAT IT COSTS, honestly: fill rate, and only fill rate. The vertices are
 * free and the fragment shader is one texture tap, but alpha-blended cards
 * cannot depth-reject each other, so every card that overlaps another pays
 * in full. See `count` in particle-fog.config.ts for the budget and the
 * two things that hold it down - the near fade shrinking cards to nothing
 * before they swallow the lens, and the far fade retiring them once the
 * distance haze has taken them anyway.
 */

export interface ParticleFogOptions {
  /** Colour when config.followSceneFog is off. From --scene-mist. */
  color: THREE.Color;
  /**
   * The scene, for its fog. Read every frame when followSceneFog is on,
   * so the banks are always the value the terrain behind them dissolves
   * into rather than a colour that was right at boot.
   */
  scene: THREE.Scene;
  lowTier: boolean;
  seed: number;
  /** Overrides for testing. Defaults to the shared live config object. */
  config?: ParticleFogConfig;
}

export interface ParticleFogRig {
  mesh: THREE.InstancedMesh;
  /**
   * Live. Writing to it re-tunes the mist on the next frame, which is the
   * only practical way to judge any of these numbers. `count` is the
   * exception - the instance buffer is sized at boot.
   */
  config: ParticleFogConfig;
  /** Seconds since boot, same clock the flags and the conifers run on. */
  update: (time: number) => void;
  /** Drift bearing in XZ, before config.windBearingOffsetDegrees. */
  setWindDirection: (x: number, z: number) => void;
  dispose: () => void;
}

/** Deterministic PRNG, so the same seed always lays the same banks. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * The puff, generated rather than downloaded.
 *
 * A fog sprite is a radial falloff with some noise bitten out of its edge,
 * which is four lines of arithmetic - a PNG of one would be another
 * request, another 30-odd KB, and a file to keep in step with a shape that
 * has no artistic content in it. Single-channel, so 128x128 is 16 KB of
 * GPU memory rather than 64.
 *
 * It must reach zero before the edge of the quad or the card shows its own
 * corners, which is what the radial term guarantees and why the noise
 * perturbs the radius rather than being added on top of the falloff.
 */
function createPuffTexture(size: number, seed: number): THREE.DataTexture {
  const random = mulberry32(seed);
  // One small lattice of random values, sampled smoothly. Three octaves is
  // enough to break the circle up; more just makes a grey disc.
  const lattice = 8;
  const grid = new Float32Array((lattice + 1) * (lattice + 1));
  for (let i = 0; i < grid.length; i++) grid[i] = random();

  const sample = (x: number, y: number): number => {
    const fx = ((x % lattice) + lattice) % lattice;
    const fy = ((y % lattice) + lattice) % lattice;
    const ix = Math.floor(fx);
    const iy = Math.floor(fy);
    const tx = fx - ix;
    const ty = fy - iy;
    const ux = tx * tx * (3 - 2 * tx);
    const uy = ty * ty * (3 - 2 * ty);
    const at = (gx: number, gy: number) => grid[(gy % lattice) * (lattice + 1) + (gx % lattice)];
    const a = at(ix, iy);
    const b = at(ix + 1, iy);
    const c = at(ix, iy + 1);
    const d = at(ix + 1, iy + 1);
    return (a + (b - a) * ux) * (1 - uy) + (c + (d - c) * ux) * uy;
  };

  const fbm = (x: number, y: number): number => {
    let sum = 0;
    let amplitude = 0.5;
    let frequency = 1;
    for (let octave = 0; octave < 3; octave++) {
      sum += sample(x * frequency, y * frequency) * amplitude;
      amplitude *= 0.5;
      frequency *= 2;
    }
    return sum / 0.875;
  };

  const data = new Uint8Array(size * size);
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const dx = (x + 0.5) / size - 0.5;
      const dy = (y + 0.5) / size - 0.5;
      // 0 at the centre, 1 on the circle inscribed in the quad.
      const radius = Math.hypot(dx, dy) * 2;
      const wobble = fbm((x / size) * 4, (y / size) * 4);
      // Perturbing the RADIUS rather than the result keeps the falloff
      // monotonic, so the edge still goes to zero however the noise lands.
      //
      // The 1.04 floor is load-bearing. The quad's inscribed circle is at
      // radius 1, but its edge MIDPOINTS are also at radius 1 - so any
      // multiplier below 1 leaves coverage there, and a card with a few
      // percent of alpha along its edge midpoints draws its own square
      // outline. A first pass used 0.78 and every bank in the scene was a
      // faintly visible rectangle.
      const shaped = radius * (1.04 + 0.5 * wobble);
      const t = Math.min(1, Math.max(0, (shaped - 0.12) / 0.88));
      let falloff = 1 - t * t * (3 - 2 * t);
      // And a hard guarantee on top of the arithmetic: whatever the noise
      // did, nothing survives to the corners.
      const corner = Math.min(1, Math.max(0, (radius - 0.86) / 0.14));
      falloff *= 1 - corner * corner * (3 - 2 * corner);
      data[y * size + x] = Math.round(Math.min(1, Math.max(0, falloff)) * 255);
    }
  }

  const texture = new THREE.DataTexture(data, size, size, THREE.RedFormat);
  // Clamped, not repeating: a card's edge sampling round to the far side
  // would wrap the blob's opposite edge back in and put a seam across it.
  texture.wrapS = THREE.ClampToEdgeWrapping;
  texture.wrapT = THREE.ClampToEdgeWrapping;
  texture.minFilter = THREE.LinearMipmapLinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.generateMipmaps = true;
  texture.colorSpace = THREE.NoColorSpace;
  texture.needsUpdate = true;
  return texture;
}

interface FogUniforms {
  uTime: { value: number };
  uPuff: { value: THREE.Texture };
  uMistColor: { value: THREE.Color };
  uOpacity: { value: number };
  /** xz drift per second. */
  uWind: { value: THREE.Vector2 };
  /** originX, originZ, extentX, extentZ - the wrap domain. */
  uDomain: { value: THREE.Vector4 };
  uEdgeFade: { value: number };
  /** nearStart, nearEnd, farStart, farEnd. */
  uRange: { value: THREE.Vector4 };
  /** amplitude, angular speed. */
  uBob: { value: THREE.Vector2 };
  uSpin: { value: number };
}

export function createParticleFog(options: ParticleFogOptions): ParticleFogRig {
  const config = options.config ?? PARTICLE_FOG;
  const count = options.lowTier ? config.count.low : config.count.high;
  const random = mulberry32(options.seed);

  const puff = createPuffTexture(128, options.seed ^ 0x51ed);

  // A unit quad. Its position attribute runs -0.5..0.5, which is both the
  // corner offset the billboard needs and, plus a half, the puff's uv -
  // so the card needs no uv attribute of its own.
  const geometry = new THREE.PlaneGeometry(1, 1);

  /**
   * Per-card randoms: size, starting angle, phase, alpha multiplier.
   *
   * In their own instanced attribute rather than squeezed into the
   * instance matrix, because the matrix carries the card's position and
   * nothing else - the billboard is built in view space, so an instance
   * rotation or scale would have no meaning by the time it was read.
   */
  const particles = new Float32Array(count * 4);
  const offsets = new Float32Array(count * 16);
  const matrix = new THREE.Matrix4();
  const position = new THREE.Vector3();
  const identityQuaternion = new THREE.Quaternion();
  const unitScale = new THREE.Vector3(1, 1, 1);

  const half = config.domainSize / 2;
  for (let i = 0; i < count; i++) {
    position.set(
      (random() * 2 - 1) * half,
      config.altitude + (random() * 2 - 1) * config.altitudeSpread,
      (random() * 2 - 1) * half,
    );
    matrix.compose(position, identityQuaternion, unitScale);
    matrix.toArray(offsets, i * 16);

    particles[i * 4] = config.sizeMin + random() * (config.sizeMax - config.sizeMin);
    particles[i * 4 + 1] = random() * Math.PI * 2;
    particles[i * 4 + 2] = random() * Math.PI * 2;
    particles[i * 4 + 3] = 0.55 + random() * 0.45;
  }
  geometry.setAttribute("aParticle", new THREE.InstancedBufferAttribute(particles, 4));

  const uniforms: FogUniforms = {
    uTime: { value: 0 },
    uPuff: { value: puff },
    uMistColor: { value: options.color.clone() },
    uOpacity: { value: config.opacity },
    uWind: { value: new THREE.Vector2(config.windSpeed, 0) },
    uDomain: {
      value: new THREE.Vector4(-half, -half, config.domainSize, config.domainSize),
    },
    uEdgeFade: { value: config.edgeFade },
    uRange: {
      value: new THREE.Vector4(
        config.nearFadeStart,
        config.nearFadeEnd,
        config.farFadeStart,
        config.farFadeEnd,
      ),
    },
    uBob: { value: new THREE.Vector2(config.bobAmplitude, (Math.PI * 2) / config.bobPeriod) },
    uSpin: { value: THREE.MathUtils.degToRad(config.spinSpeed) },
  };

  const material = new THREE.MeshBasicMaterial({
    transparent: true,
    // Off, and this is the one that matters most. Cards overlap constantly
    // and writing depth would have each one occlude the ones behind it,
    // which is a hole in the mist shaped like a quad. They still TEST
    // against the terrain's depth, so a bank behind the mountain stays
    // behind it.
    depthWrite: false,
    // The billboard is assembled in view space, where "which way the quad
    // faces" is no longer a property of the geometry - so rather than
    // reason about the winding that comes out, take both. It costs
    // nothing: only one face of a camera-facing quad ever rasterises.
    side: THREE.DoubleSide,
    // The distance haze applies to the mist too. Without it a near bank
    // and a far one are the same value and the layer reads flat.
    fog: true,
  });

  material.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);

    shader.vertexShader = shader.vertexShader
      .replace(
        "#include <common>",
        /* glsl */ `#include <common>
        attribute vec4 aParticle;
        uniform float uTime;
        uniform vec2 uWind;
        uniform vec4 uDomain;
        uniform float uEdgeFade;
        uniform vec4 uRange;
        uniform vec2 uBob;
        uniform float uSpin;
        uniform float uOpacity;
        varying float vAlpha;
        varying vec2 vPuffUv;`,
      )
      .replace(
        "#include <project_vertex>",
        /* glsl */ `
        /* Replaces three's project_vertex outright, because a billboard is
           not a transform of the mesh - the quad is built from scratch in
           VIEW space so it faces the camera whatever the camera is doing.
           mvPosition has to be declared here under that exact name:
           <fog_vertex>, a few chunks further down, reads it. */
        vec3 npdBase = (modelMatrix * instanceMatrix * vec4(0.0, 0.0, 0.0, 1.0)).xyz;

        /* Drift, wrapped back into the domain. GLSL's mod is the
           floor-based one, so this lands in [origin, origin + extent) for
           any uTime, however large it has grown - which is what lets the
           whole motion be a pure function of time with no state to
           advance and nothing to re-upload. */
        vec2 npdDrift = npdBase.xz + uWind * uTime;
        vec2 npdWrapped = mod(npdDrift - uDomain.xy, uDomain.zw) + uDomain.xy;

        float npdBob = sin(uTime * uBob.y + aParticle.z) * uBob.x;
        vec3 npdCenter = vec3(npdWrapped.x, npdBase.y + npdBob, npdWrapped.y);

        vec4 mvPosition = viewMatrix * vec4(npdCenter, 1.0);
        float npdDistance = -mvPosition.z;

        /* Three fades. The wrap one hides the teleport at the domain edge,
           the other two are the distance window the card is allowed to
           exist in. */
        vec2 npdEdge = min(npdWrapped - uDomain.xy, uDomain.xy + uDomain.zw - npdWrapped);
        float npdWrapFade = smoothstep(0.0, uEdgeFade, min(npdEdge.x, npdEdge.y));
        float npdNear = smoothstep(uRange.x, uRange.y, npdDistance);
        float npdFar = 1.0 - smoothstep(uRange.z, uRange.w, npdDistance);

        /* The near fade also SHRINKS the card, and that is a fill-rate
           decision rather than a look. A card the camera is about to
           reach covers most of the viewport; fading it by alpha alone
           still rasterises every one of those fragments just to multiply
           them by zero. Collapsing it toward a point means they are never
           generated. The far fade does not need this - a card that far
           off is already small on screen. */
        float npdSize = aParticle.x * npdNear;

        float npdSpinDir = step(3.14159, aParticle.z) * 2.0 - 1.0;
        float npdAngle = aParticle.y + uTime * uSpin * npdSpinDir;
        float npdSin = sin(npdAngle);
        float npdCos = cos(npdAngle);
        vec2 npdCorner = position.xy * npdSize;
        mvPosition.xy += vec2(
          npdCorner.x * npdCos - npdCorner.y * npdSin,
          npdCorner.x * npdSin + npdCorner.y * npdCos
        );

        gl_Position = projectionMatrix * mvPosition;

        vAlpha = uOpacity * aParticle.w * npdWrapFade * npdNear * npdFar;
        /* The plane's own position IS the uv, offset by a half - so the
           card carries no uv attribute and the geometry stays four
           vertices of position alone. */
        vPuffUv = position.xy + 0.5;`,
      );

    shader.fragmentShader = shader.fragmentShader
      .replace(
        "#include <common>",
        /* glsl */ `#include <common>
        uniform sampler2D uPuff;
        uniform vec3 uMistColor;
        varying float vAlpha;
        varying vec2 vPuffUv;`,
      )
      .replace(
        "#include <color_fragment>",
        /* glsl */ `
        /* Single channel: the puff is a coverage mask, not a picture. The
           colour is the same for every fragment of every card and comes
           from a uniform. */
        diffuseColor = vec4(uMistColor, vAlpha * texture2D(uPuff, vPuffUv).r);`,
      );
  };
  material.customProgramCacheKey = () => "npd-particle-fog";

  const mesh = new THREE.InstancedMesh(geometry, material, count);
  mesh.instanceMatrix.copyArray(offsets);
  mesh.instanceMatrix.needsUpdate = true;
  mesh.instanceMatrix.setUsage(THREE.StaticDrawUsage);
  // The cards move in the shader, so nothing three can compute from the
  // instance matrices describes where they actually are. Culling is no
  // loss anyway: the banks fill the valley the camera spends the whole
  // page pointed into, so a correct bounding volume would be on screen in
  // every frame regardless.
  mesh.frustumCulled = false;
  mesh.castShadow = false;
  mesh.receiveShadow = false;
  // After the terrain, the trail and the flags. Transparent objects are
  // drawn last anyway; this only fixes the order among them, so the mist
  // lands over the summit flag rather than being sorted under it by
  // whichever happens to be nearer the camera this frame.
  mesh.renderOrder = 2;

  const windDirection = new THREE.Vector2(1, 0);

  const applyWind = () => {
    const offset = THREE.MathUtils.degToRad(config.windBearingOffsetDegrees);
    const cos = Math.cos(offset);
    const sin = Math.sin(offset);
    uniforms.uWind.value
      .set(
        windDirection.x * cos - windDirection.y * sin,
        windDirection.x * sin + windDirection.y * cos,
      )
      .multiplyScalar(config.windSpeed);
  };
  applyWind();

  return {
    mesh,
    config,
    update: (time: number) => {
      uniforms.uTime.value = time;

      // Pulled from the config every frame rather than at boot, which is
      // what makes editing particle-fog.config.ts in a running page - or
      // the object itself from the console - show up immediately. It is a
      // dozen assignments on an object that is already in cache; the
      // alternative is a setter per knob and a stale one the day someone
      // forgets to add it.
      uniforms.uOpacity.value = config.opacity;
      uniforms.uEdgeFade.value = config.edgeFade;
      uniforms.uRange.value.set(
        config.nearFadeStart,
        config.nearFadeEnd,
        config.farFadeStart,
        config.farFadeEnd,
      );
      uniforms.uBob.value.set(config.bobAmplitude, (Math.PI * 2) / Math.max(1e-3, config.bobPeriod));
      uniforms.uSpin.value = THREE.MathUtils.degToRad(config.spinSpeed);
      applyWind();

      if (config.followSceneFog && options.scene.fog) {
        uniforms.uMistColor.value.copy(options.scene.fog.color);
      } else {
        uniforms.uMistColor.value.copy(options.color);
      }
      uniforms.uMistColor.value.multiplyScalar(config.brightness);
    },
    setWindDirection: (x: number, z: number) => {
      windDirection.set(x, z);
      // A zero-length bearing would normalize to NaN and take every card
      // in the scene with it.
      if (windDirection.lengthSq() > 1e-8) windDirection.normalize();
      else windDirection.set(1, 0);
      applyWind();
    },
    dispose: () => {
      geometry.dispose();
      material.dispose();
      puff.dispose();
    },
  };
}
