import * as THREE from "three";

/**
 * MeshStandardMaterial extended via onBeforeCompile - keeps the standard
 * physically-based lighting model, only the colour and the detail normal
 * are replaced.
 *
 * The mountain is four surfaces, not one: alpine tundra in the valley,
 * scree where the slope has eased below the snowline, slate rock on
 * everything steep, and wind-packed snow on the caps. Which one a fragment
 * gets is decided by altitude and slope - never by a painted mask - so the
 * same material serves the massif, the apron and the far range without any
 * of them carrying its own texture set.
 *
 * All four grains arrive in ONE texture, a channel each (R rock, G snow,
 * B scree, A tundra - see scripts/pack-terrain-detail.mjs). That is what
 * makes this affordable on a phone: the projection is triplanar, so it is
 * three fetches per fragment for all four surfaces rather than three per
 * surface.
 *
 * Colour still comes from the tokens in tokens.css. The texture supplies
 * only the grain - high-passed, centred on 0.5 - and the token supplies
 * what that grain is made of, which is what keeps the mountain repainting
 * with the theme rather than carrying a second palette inside a PNG.
 */
export interface TerrainMaterialOptions {
  rockColor: THREE.Color;
  snowColor: THREE.Color;
  /** Broken rock below the snowline. Falls back to a darkened rock colour. */
  screeColor?: THREE.Color;
  /** Heath and lichen below the treeline. Falls back to the rock colour. */
  tundraColor?: THREE.Color;
  /**
   * The packed grain map. Optional only so a material can be built before
   * it has downloaded - absent, every channel reads a flat 0.5 and the
   * surfaces come out as their untextured token colours, which is the same
   * picture this material drew before there was a texture at all.
   */
  detailMap?: THREE.Texture | null;
  /** World-space Y where snow starts to be eligible, before slope/noise. */
  snowlineHeight: number;
  /** Vertical distance over which the snowline fades in. */
  snowlineBlend?: number;
  /**
   * World-space Y below which vegetation takes over. Push it below the
   * mesh (a large negative) to turn the band off entirely - that is how a
   * surface opts out of being green, the same way snowlineHeight above the
   * mesh is how it opts out of being white.
   */
  treelineHeight?: number;
  treelineBlend?: number;
  /** dot(normal, up) below this: never snow, regardless of height. */
  slopeThresholdLow?: number;
  /** dot(normal, up) above this: fully snow-eligible. */
  slopeThresholdHigh?: number;
  /** Same pair for vegetation, which needs flatter ground than snow does. */
  tundraSlopeLow?: number;
  tundraSlopeHigh?: number;
  /** And for scree, which gathers on slopes between the two. */
  screeSlopeLow?: number;
  screeSlopeHigh?: number;
  /** How much of the eligible area scree is allowed to claim, 0..1. */
  screeAmount?: number;
  /** World units across one tile of the grain map. */
  detailTileSize?: number;
  /**
   * Strength of the detail bump, 0..1. Zero is not just "flat" - it skips
   * the derivative work entirely, which is why the low tier passes 0 rather
   * than a small number.
   */
  detailBump?: number;
  /**
   * View distances, in world units, over which the bump fades to nothing.
   *
   * Not an aesthetic taper - a correctness one. The bump is the screen-
   * space derivative of a sampled grain, so its strength is whatever the
   * texture happens to do between two adjacent pixels. Close up that is
   * the rock. Far off, where one pixel spans many texels, it is whichever
   * texel the mip happened to land on - pure aliasing, and it renders as a
   * crawling sparkle over the whole upper mountain. Past the far value the
   * grain is still there in the colour; only the lighting stops pretending
   * to resolve it.
   */
  detailBumpFadeNear?: number;
  detailBumpFadeFar?: number;
  /** World-unit period of the low-frequency variation that breaks the tile. */
  macroScale?: number;
  /** How hard that variation pushes, 0..1. */
  macroAmount?: number;
  /** World-unit amplitude of the low-frequency snowline perturbation. */
  snowlineNoiseAmp?: number;
  /** Frequency of the low-frequency snowline perturbation. */
  snowlineNoiseScale?: number;
}

/**
 * A 1x1 mid-grey stand-in, shared by every material built before the real
 * map lands. A sampler that is never bound is undefined behaviour rather
 * than black, so there has to be something in it; 0.5 is the value the
 * packed grain is centred on, so binding this reads as "no grain" instead
 * of as a dark or light wash over the whole mountain.
 */
let neutralDetail: THREE.DataTexture | null = null;
function neutralDetailMap(): THREE.DataTexture {
  if (!neutralDetail) {
    neutralDetail = new THREE.DataTexture(new Uint8Array([128, 128, 128, 128]), 1, 1);
    neutralDetail.needsUpdate = true;
  }
  return neutralDetail;
}

export interface TerrainUniforms {
  uDetailMap: { value: THREE.Texture };
  uDetailScale: { value: number };
  uDetailBump: { value: number };
  uBumpFade: { value: THREE.Vector2 };
  uRockColor: { value: THREE.Color };
  uSnowColor: { value: THREE.Color };
  uScreeColor: { value: THREE.Color };
  uTundraColor: { value: THREE.Color };
  uSnowlineHeight: { value: number };
  uSnowlineBlend: { value: number };
  uTreelineHeight: { value: number };
  uTreelineBlend: { value: number };
  uSlopeLow: { value: number };
  uSlopeHigh: { value: number };
  uTundraSlope: { value: THREE.Vector2 };
  uScreeSlope: { value: THREE.Vector2 };
  uScreeAmount: { value: number };
  uMacroScale: { value: number };
  uMacroAmount: { value: number };
  uSnowlineNoiseAmp: { value: number };
  uSnowlineNoiseScale: { value: number };
}

export type TerrainMaterial = THREE.MeshStandardMaterial & {
  userData: { terrainUniforms: TerrainUniforms };
};

export function createTerrainMaterial(options: TerrainMaterialOptions): TerrainMaterial {
  const material = new THREE.MeshStandardMaterial({
    color: options.rockColor,
    roughness: 0.92,
    metalness: 0.0,
    // The rock/snow blend and the exp2 fog are both smooth gradients over a
    // large surface - without dithering, ACES tone mapping quantizes that
    // into visible banding steps.
    dithering: true,
  }) as TerrainMaterial;

  const tile = options.detailTileSize ?? 90;

  const uniforms: TerrainUniforms = {
    uDetailMap: { value: options.detailMap ?? neutralDetailMap() },
    uDetailScale: { value: 1 / tile },
    uDetailBump: { value: options.detailBump ?? 0 },
    uBumpFade: {
      value: new THREE.Vector2(
        options.detailBumpFadeNear ?? 90,
        options.detailBumpFadeFar ?? 340,
      ),
    },
    uRockColor: { value: options.rockColor },
    uSnowColor: { value: options.snowColor },
    // Scree with no colour of its own is rock, slightly greyed down - the
    // band still reads, because its grain is the cobble plate rather than
    // the strata one, and it costs nothing to get wrong.
    uScreeColor: {
      value: options.screeColor ?? options.rockColor.clone().multiplyScalar(0.88),
    },
    uTundraColor: { value: options.tundraColor ?? options.rockColor },
    uSnowlineHeight: { value: options.snowlineHeight },
    uSnowlineBlend: { value: options.snowlineBlend ?? 16.0 },
    // Default is far below anything this scene builds, so a caller that
    // says nothing about a treeline gets no vegetation rather than a
    // surprise green mountain.
    uTreelineHeight: { value: options.treelineHeight ?? -1e6 },
    uTreelineBlend: { value: options.treelineBlend ?? 14.0 },
    uSlopeLow: { value: options.slopeThresholdLow ?? -0.05 },
    uSlopeHigh: { value: options.slopeThresholdHigh ?? 0.3 },
    uTundraSlope: {
      value: new THREE.Vector2(options.tundraSlopeLow ?? 0.55, options.tundraSlopeHigh ?? 0.86),
    },
    uScreeSlope: {
      value: new THREE.Vector2(options.screeSlopeLow ?? 0.42, options.screeSlopeHigh ?? 0.78),
    },
    uScreeAmount: { value: options.screeAmount ?? 0.85 },
    uMacroScale: { value: 1 / (options.macroScale ?? tile * 3.4) },
    uMacroAmount: { value: options.macroAmount ?? 0.35 },
    uSnowlineNoiseAmp: { value: options.snowlineNoiseAmp ?? 9.0 },
    uSnowlineNoiseScale: { value: options.snowlineNoiseScale ?? 0.015 },
  };

  material.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);

    shader.vertexShader = shader.vertexShader
      .replace(
        "#include <common>",
        `#include <common>
        varying vec3 vWorldPosition;
        varying vec3 vWorldNormal;`
      )
      .replace(
        "#include <beginnormal_vertex>",
        `#include <beginnormal_vertex>
        vWorldNormal = normalize(mat3(modelMatrix) * objectNormal);`
      )
      .replace(
        "#include <begin_vertex>",
        `#include <begin_vertex>
        vWorldPosition = (modelMatrix * vec4(transformed, 1.0)).xyz;`
      );

    shader.fragmentShader = shader.fragmentShader
      .replace(
        "#include <common>",
        `#include <common>
        varying vec3 vWorldPosition;
        varying vec3 vWorldNormal;
        uniform sampler2D uDetailMap;
        uniform float uDetailScale;
        uniform float uDetailBump;
        uniform vec2 uBumpFade;
        uniform vec3 uRockColor;
        uniform vec3 uSnowColor;
        uniform vec3 uScreeColor;
        uniform vec3 uTundraColor;
        uniform float uSnowlineHeight;
        uniform float uSnowlineBlend;
        uniform float uTreelineHeight;
        uniform float uTreelineBlend;
        uniform float uSlopeLow;
        uniform float uSlopeHigh;
        uniform vec2 uTundraSlope;
        uniform vec2 uScreeSlope;
        uniform float uScreeAmount;
        uniform float uMacroScale;
        uniform float uMacroAmount;
        uniform float uSnowlineNoiseAmp;
        uniform float uSnowlineNoiseScale;

        float terrainHash(vec2 p) {
          p = fract(p * vec2(234.34, 435.345));
          p += dot(p, p + 34.23);
          return fract(p.x * p.y);
        }

        float terrainValueNoise(vec2 p) {
          vec2 i = floor(p);
          vec2 f = fract(p);
          float a = terrainHash(i);
          float b = terrainHash(i + vec2(1.0, 0.0));
          float c = terrainHash(i + vec2(0.0, 1.0));
          float d = terrainHash(i + vec2(1.0, 1.0));
          vec2 u = f * f * (3.0 - 2.0 * f);
          return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
        }

        /* All four grains at once. The blend weights are the squared
           normal rather than its absolute value: |n| leaves a wide band
           near a 45-degree face where two projections are mixed half and
           half, and a half-and-half mix of two independent grain fields
           is visibly softer than either of them. Squaring narrows that
           band to where the eye stops noticing it. */
        vec4 terrainTriplanar(vec3 pos, vec3 normal, float scale) {
          vec3 blend = normal * normal;
          blend = blend / (blend.x + blend.y + blend.z + 1e-5);
          vec4 nx = texture2D(uDetailMap, pos.yz * scale);
          vec4 ny = texture2D(uDetailMap, pos.xz * scale);
          vec4 nz = texture2D(uDetailMap, pos.xy * scale);
          return nx * blend.x + ny * blend.y + nz * blend.z;
        }

        /* Grain and macro variation, combined into the one number every
           surface colour is multiplied by.

           Added rather than multiplied, and clamped. Multiplying two
           independent +/-25% terms gives a 0.48..1.70 envelope, and the
           low end of that is not a lighting choice - it is a contrast
           failure. This mountain sits BEHIND body copy, and in day mode
           the rock is a pale #b6c2d4 chosen to clear 9.7:1 against navy
           text. A fragment at 0.48 of it clears 3.5:1 and the paragraph
           over it stops being readable. The floor here holds the darkest
           the terrain can ever get to about 5.3:1, before the sun has
           said anything. */
        float terrainShade(float grain, float macro) {
          return clamp(0.78 + 0.40 * grain + macro * 0.16, 0.74, 1.22);
        }`
      )
      .replace(
        "#include <color_fragment>",
        `
        vec3 terrainWorldNormal = normalize(vWorldNormal);
        vec4 terrainGrain = terrainTriplanar(vWorldPosition, terrainWorldNormal, uDetailScale);

        /* One tile of the grain map is 90 world units and the massif is
           620 across, so the map lays down about seven repeats over the
           whole mountain - close enough to spot. This is what hides the
           repeat: a noise field at several times the tile period, which
           the tile cannot line up with, brightening and darkening whole
           slopes so no two repeats read the same. */
        float terrainMacro = (terrainValueNoise(vWorldPosition.xz * uMacroScale) * 2.0 - 1.0) * uMacroAmount;

        float terrainUp = dot(terrainWorldNormal, vec3(0.0, 1.0, 0.0));

        /* Both band edges wobble on the same noise. Sharing it is
           deliberate - they are the same mountain's weather, and driving
           them from two independent fields makes the scree band between
           them pinch and swell in a way that reads as an error. */
        float terrainBandNoise = terrainValueNoise(vWorldPosition.xz * uSnowlineNoiseScale) * 2.0 - 1.0;

        float terrainSnowline = uSnowlineHeight + terrainBandNoise * uSnowlineNoiseAmp;
        float terrainSnowFactor =
          smoothstep(terrainSnowline - uSnowlineBlend, terrainSnowline + uSnowlineBlend, vWorldPosition.y) *
          smoothstep(uSlopeLow, uSlopeHigh, terrainUp);

        float terrainTreeline = uTreelineHeight + terrainBandNoise * uSnowlineNoiseAmp * 0.7;
        float terrainTundraFactor =
          (1.0 - smoothstep(terrainTreeline - uTreelineBlend, terrainTreeline + uTreelineBlend, vWorldPosition.y)) *
          smoothstep(uTundraSlope.x, uTundraSlope.y, terrainUp);

        /* Scree is what is left over: the slope has eased enough for
           broken rock to sit on it, but it is neither vegetated nor
           snowed. Modulated by the macro field as well, because a talus
           fan is a patch on a mountainside, not a belt around it. */
        float terrainScreeFactor =
          smoothstep(uScreeSlope.x, uScreeSlope.y, terrainUp) *
          (1.0 - terrainTundraFactor) *
          (1.0 - terrainSnowFactor) *
          uScreeAmount *
          smoothstep(-0.55 * uMacroAmount, 0.6 * uMacroAmount, terrainMacro);

        vec3 terrainRock = uRockColor * terrainShade(terrainGrain.r, terrainMacro);
        vec3 terrainScree = uScreeColor * terrainShade(terrainGrain.b, terrainMacro);
        vec3 terrainTundra = uTundraColor * terrainShade(terrainGrain.a, terrainMacro);
        /* Snow gets a fraction of the others' grain range and none of the
           macro variation. It is the brightest thing in the frame and the
           one the tone mapper is closest to clipping, so contrast spent
           here buys nothing and costs the form in the caps. */
        vec3 terrainBrightSnow = min(uSnowColor * (0.93 + 0.16 * terrainGrain.g), vec3(1.0));

        vec3 terrainColor = terrainRock;
        terrainColor = mix(terrainColor, terrainScree, terrainScreeFactor);
        terrainColor = mix(terrainColor, terrainTundra, terrainTundraFactor);
        terrainColor = mix(terrainColor, terrainBrightSnow, terrainSnowFactor);

        /* The same blend again, over the grain values rather than the
           colours, so the bump below is the height field of whichever
           surface actually won here instead of an average of four. */
        float terrainHeight = terrainGrain.r;
        terrainHeight = mix(terrainHeight, terrainGrain.b, terrainScreeFactor);
        terrainHeight = mix(terrainHeight, terrainGrain.a, terrainTundraFactor);
        terrainHeight = mix(terrainHeight, terrainGrain.g, terrainSnowFactor);

        diffuseColor = vec4(terrainColor, opacity);

        /* snow gets a small light-independent glow so it still reads as
           snow under the warm ambient, which would otherwise tint it the
           same stone colour as lit rock and erase the contrast. Cut from
           0.3: at that strength it was self-illuminating the caps into a
           flat silhouette with no form left in them. */
        totalEmissiveRadiance += uSnowColor * terrainSnowFactor * 0.1;
        `
      )
      .replace(
        "#include <roughnessmap_fragment>",
        `#include <roughnessmap_fragment>
        /* Snow is packed and slightly glazed; scree and heath are neither.
           A quarter of a roughness step either way is not much, but it is
           what stops the snowline being a colour change alone - the caps
           now pick up a sheen from the sun that the rock below them does
           not. */
        roughnessFactor *= 1.0 - 0.22 * terrainSnowFactor + 0.05 * terrainScreeFactor;
        `
      )
      .replace(
        "#include <normal_fragment_maps>",
        `#include <normal_fragment_maps>
        /* Detail bump, from the grain that was already fetched for colour -
           no second texture, no tangents, no normal map. Mikkelsen's
           surface-gradient form: the screen-space derivative of the grain
           is turned into a gradient along the real surface using the
           derivatives of world position, which is what makes the strength
           independent of how the terrain happens to be scaled or oriented.

           Off on the low tier, and off means off: the branch skips the
           four derivative pairs rather than multiplying their result by
           zero. Derivatives are quad-level work on every fragment in
           flight, which is exactly what a phone has least of. The same
           branch retires the far field, where the bump is aliasing rather
           than rock - see detailBumpFadeFar. */
        float terrainBump = uDetailBump *
          (1.0 - smoothstep(uBumpFade.x, uBumpFade.y, distance(vWorldPosition, cameraPosition)));
        if (terrainBump > 0.001) {
          vec3 terrainDpdx = dFdx(vWorldPosition);
          vec3 terrainDpdy = dFdy(vWorldPosition);
          vec3 terrainR1 = cross(terrainDpdy, normal);
          vec3 terrainR2 = cross(normal, terrainDpdx);
          float terrainDet = dot(terrainDpdx, terrainR1);
          vec3 terrainGradient =
            sign(terrainDet) * (dFdx(terrainHeight) * terrainR1 + dFdy(terrainHeight) * terrainR2);
          normal = normalize(abs(terrainDet) * normal - terrainBump * terrainGradient);
        }
        `
      );
  };

  // Constant, and safe to be: every material built here compiles the same
  // source, and everything that differs between them - colours, band
  // heights, whether the bump runs - is a uniform. three appends this to
  // its own parameter key rather than replacing it, so the things that DO
  // change the program (fog, shadows, instancing) are still accounted for.
  material.customProgramCacheKey = () => "npd-terrain-bands";
  material.userData.terrainUniforms = uniforms;

  return material;
}
