import * as THREE from "three";
import type { TerrainSampler } from "./terrain-sampler";

/**
 * The conifer belt: one InstancedMesh, one draw call, a few thousand trees.
 *
 * The tree is built here rather than loaded. That is not for want of
 * looking - it is what the budget wants. A downloaded conifer is a glTF
 * plus a loader in the bundle plus an albedo atlas, and if it is *animated*
 * it is a skinned mesh, which cannot be instanced at all: every tree
 * becomes its own draw call with its own bone texture. Thirty-four
 * triangles generated at boot cost no bytes over the wire, instance in one
 * call, and sway in the vertex shader for free - which is the same
 * animation a skinned tree would have given, arrived at from the side that
 * a phone can afford.
 *
 * Trees do not cast shadows. Same reasoning the trail is not a caster: a
 * few thousand instances re-rendered into the sun's shadow map is the most
 * expensive thing this scene could ask for, and what it buys is a stipple
 * of acne under objects already sitting in the terrain's own shadow.
 */

/**
 * One ring of planting, on one surface.
 *
 * Zones exist because the belt is not all one forest. The near one stands
 * on the massif and is read at a hundred pixels a tree; the far ones stand
 * on the plain and the foothills behind it and are read at fifteen, mostly
 * through fog. They want different densities, different grove sizes and
 * different samplers - but they do NOT want different meshes, because the
 * whole argument for instancing is that the entire belt is one draw call.
 * So every zone writes into the same buffer.
 */
export interface TreeZone {
  /** The surface this ring is planted on. */
  sampler: TerrainSampler;
  /**
   * The ring, in world units from the origin. Planting must stay inside
   * the sampler's own extent: outside it heightAt clamps to the edge row
   * and starts reporting a height the ground does not actually have,
   * which leaves trees standing above or sunk into flat plain - the one
   * placement error that reads instantly.
   */
  innerRadius: number;
  outerRadius: number;
  /** How many to plant here. The placement rules may return fewer. */
  count: number;
  /**
   * The mesh's own Y, added to every sampled height. A sampler describes
   * its heightmap, not where the mesh carrying it was put in the scene -
   * and the far range sits below zero.
   */
  heightOffset?: number;
  /**
   * World-space Y the belt thins out at. Density ramps to nothing over
   * the last fifth of the way up to it, so the belt ends in stragglers
   * rather than on a contour line.
   */
  treelineHeight: number;
  /** Nothing plants below this - keeps the belt off the apron's flat rim. */
  minPlantingHeight?: number;
  /** dot(normal, up) a slope must reach to hold trees. */
  minSlope?: number;
  /** World units across one grove cell - bigger means broader stands. */
  groveScale?: number;
  /** Grove noise below this is a clearing. Higher leaves more open ground. */
  groveThreshold?: number;
  /** Trunk-to-tip height in world units, before the treeline scrubs it down. */
  minSize?: number;
  maxSize?: number;
}

export interface TreeOptions {
  /** Planting rings, nearest first. All of them land in one mesh. */
  zones: TreeZone[];
  seed: number;
  /** The massif's footprint - the extent the trail keep-out grid covers. */
  worldSize: number;
  /**
   * The climb, as world-space points. Trees keep clear of it: the line and
   * its flags are the one thing on this mountain the page is about, and a
   * conifer standing on the trail hides a switchback.
   */
  avoid?: THREE.Vector3[];
  avoidRadius?: number;
  canopyColor: THREE.Color;
  /** Canopy at the tips, where the light reaches. */
  canopyLitColor: THREE.Color;
  trunkColor: THREE.Color;
  /** Shadow receipt is the one thing here that is not free. Off on mobile. */
  receiveShadow?: boolean;
}

export interface TreesResult {
  mesh: THREE.InstancedMesh;
  /** How many were actually planted after the placement rules had their say. */
  planted: number;
  /** Per zone, in the order they were given - for tuning density by eye. */
  plantedPerZone: number[];
  /** Advances the wind. Seconds since boot, same clock the flags run on. */
  update: (time: number) => void;
  /**
   * Which way the belt leans, as a compass direction in XZ.
   *
   * Set from outside rather than picked here for the same reason the sun's
   * azimuth is: a direction hard-coded in this module would go on pointing
   * at the old flank the first time the trail is retuned, and sway along
   * the camera's own axis is sway nobody can see.
   */
  setWindDirection: (x: number, z: number) => void;
}

/** Sides on the canopy cones. Seven reads round enough at this size. */
const CANOPY_SIDES = 7;
/** Sides on the trunk. Three, because nobody has ever counted them. */
const TRUNK_SIDES = 3;
/** Stacked cones per canopy. */
const CANOPY_TIERS = 3;

/** Deterministic PRNG, so the same seed always plants the same forest. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Smooth 2D value noise, for grouping trees into groves.
 *
 * Uniform rejection sampling gives an even scatter, and an even scatter of
 * trees reads as wallpaper. A real belt is patchy - denser in the gullies,
 * thinner on the spurs - and one octave of noise gating the accept test is
 * the whole difference.
 */
function groveNoise(x: number, y: number, seed: number): number {
  const hash = (ix: number, iy: number) => {
    let h = Math.imul(ix, 374761393) ^ Math.imul(iy, 668265263) ^ Math.imul(seed, 2246822519);
    h = Math.imul(h ^ (h >>> 13), 1274126177);
    return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
  };
  const ix = Math.floor(x);
  const iy = Math.floor(y);
  const fx = x - ix;
  const fy = y - iy;
  const ux = fx * fx * (3 - 2 * fx);
  const uy = fy * fy * (3 - 2 * fy);
  const a = hash(ix, iy);
  const b = hash(ix + 1, iy);
  const c = hash(ix, iy + 1);
  const d = hash(ix + 1, iy + 1);
  return (a + (b - a) * ux) * (1 - uy) + (c + (d - c) * ux) * uy;
}

interface ConiferGeometry {
  geometry: THREE.BufferGeometry;
  /** Total height of the unit tree, so instance scales read as world units. */
  height: number;
}

/**
 * One conifer, origin at the foot of the trunk, +Y up.
 *
 * Non-indexed on purpose: every vertex carries its own colour and its own
 * sway weight, and sharing a vertex between two cone tiers would have to
 * average both. At thirty-four triangles the index buffer was never going
 * to be the saving.
 */
function buildConifer(
  canopyColor: THREE.Color,
  canopyLitColor: THREE.Color,
  trunkColor: THREE.Color,
): ConiferGeometry {
  const trunkHeight = 0.26;
  const trunkRadius = 0.05;
  const height = 1;

  const positions: number[] = [];
  const colors: number[] = [];
  const sways: number[] = [];

  /**
   * Sway weight for a vertex at height y. Quadratic rather than linear:
   * a trunk bends much less than the crown it carries, and a linear ramp
   * puts visible motion at ankle height where a tree has none.
   */
  const swayAt = (y: number) => Math.pow(Math.min(1, Math.max(0, y / height)), 1.7);

  const push = (x: number, y: number, z: number, color: THREE.Color) => {
    positions.push(x, y, z);
    colors.push(color.r, color.g, color.b);
    sways.push(swayAt(y));
  };

  // --- trunk: a prism, no caps. The bottom is in the ground and the top
  // is inside the lowest cone, so both caps are triangles nobody sees.
  for (let i = 0; i < TRUNK_SIDES; i++) {
    const a = (i / TRUNK_SIDES) * Math.PI * 2;
    const b = ((i + 1) / TRUNK_SIDES) * Math.PI * 2;
    const ax = Math.cos(a) * trunkRadius;
    const az = Math.sin(a) * trunkRadius;
    const bx = Math.cos(b) * trunkRadius;
    const bz = Math.sin(b) * trunkRadius;
    push(bx, 0, bz, trunkColor);
    push(ax, 0, az, trunkColor);
    push(ax, trunkHeight, az, trunkColor);
    push(bx, 0, bz, trunkColor);
    push(ax, trunkHeight, az, trunkColor);
    push(bx, trunkHeight, bz, trunkColor);
  }

  // --- canopy: cones that get narrower and shorter toward the top, each
  // overlapping the one below so no gap opens at a tier boundary.
  for (let tier = 0; tier < CANOPY_TIERS; tier++) {
    const t = tier / CANOPY_TIERS;
    const baseY = trunkHeight * 0.72 + (height - trunkHeight * 0.72) * t * 0.78;
    const topY = baseY + (height - baseY) * (tier === CANOPY_TIERS - 1 ? 1 : 0.62);
    const radius = 0.3 * (1 - t * 0.62);

    // Tips catch the light, skirts sit in the tree's own shade. The ramp
    // runs over the whole tree rather than per tier, so the gradient reads
    // as one canopy lit from above and not as three striped cones.
    const skirt = canopyColor.clone().lerp(canopyLitColor, (baseY / height) * 0.45);
    const tip = canopyColor.clone().lerp(canopyLitColor, 0.25 + (topY / height) * 0.75);

    for (let i = 0; i < CANOPY_SIDES; i++) {
      const a = (i / CANOPY_SIDES) * Math.PI * 2;
      const b = ((i + 1) / CANOPY_SIDES) * Math.PI * 2;
      const ax = Math.cos(a) * radius;
      const az = Math.sin(a) * radius;
      const bx = Math.cos(b) * radius;
      const bz = Math.sin(b) * radius;
      push(bx, baseY, bz, skirt);
      push(ax, baseY, az, skirt);
      push(0, topY, 0, tip);

      // Only the lowest skirt is closed. The others sit over a cone that
      // already fills the hole.
      if (tier === 0) {
        push(0, baseY, 0, skirt);
        push(ax, baseY, az, skirt);
        push(bx, baseY, bz, skirt);
      }
    }
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
  geometry.setAttribute("aSway", new THREE.Float32BufferAttribute(sways, 1));
  geometry.computeVertexNormals();

  return { geometry, height };
}

interface WindUniforms {
  uTime: { value: number };
  uWindDir: { value: THREE.Vector2 };
  uWindStrength: { value: number };
}

/**
 * Lambert, not Standard. A tree here is a handful of screen pixels and the
 * scene already pays for a physically-based mountain behind it; a full PBR
 * evaluation per fragment on top buys nothing anyone can see. Flat-shaded,
 * because the whole point of a seven-sided cone is that you can count the
 * faces.
 */
function createTreeMaterial(): { material: THREE.MeshLambertMaterial; uniforms: WindUniforms } {
  const uniforms: WindUniforms = {
    uTime: { value: 0 },
    // Not a constant direction picked here - see createTrees, which takes
    // it from the same flank bearing the sun and the camera use.
    uWindDir: { value: new THREE.Vector2(1, 0) },
    uWindStrength: { value: 0.055 },
  };

  const material = new THREE.MeshLambertMaterial({
    vertexColors: true,
    flatShading: true,
  });

  material.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);

    shader.vertexShader = shader.vertexShader
      .replace(
        "#include <common>",
        /* glsl */ `#include <common>
        attribute float aSway;
        uniform float uTime;
        uniform vec2 uWindDir;
        uniform float uWindStrength;`,
      )
      .replace(
        "#include <begin_vertex>",
        /* glsl */ `#include <begin_vertex>
        /* This runs in OBJECT space, before <project_vertex> applies
           instanceMatrix - and every tree carries a random Y rotation,
           so pushing straight along uWindDir here would send each one a
           different way. A forest where every tree leans somewhere else
           is not wind, it is jitter; wind is the thing they all do at
           once.

           So the direction is rotated INTO object space first, by
           projecting it onto the instance's own axes. The instance
           matrix's columns are rotation times scale, so normalising two
           of them recovers the rotation without needing an inverse. The
           residual skew from a tree being scaled differently in x and z
           is a few degrees, and a few degrees off the wind is what a
           tree does anyway.

           The phase comes off the instance's translation column: every
           tree gets a different point in the gust with no per-instance
           attribute to upload.

           Guarded, because this same material compiles for a non-
           instanced mesh in ?debug, where instanceMatrix does not exist
           and referencing it is a link error, not a warning. */
        vec3 npdWind = vec3(uWindDir.x, 0.0, uWindDir.y);
        #ifdef USE_INSTANCING
          vec3 npdTreeOrigin = instanceMatrix[3].xyz;
          vec2 npdLocalWind = vec2(
            dot(npdWind, normalize(instanceMatrix[0].xyz)),
            dot(npdWind, normalize(instanceMatrix[2].xyz))
          );
        #else
          vec3 npdTreeOrigin = vec3(0.0);
          vec2 npdLocalWind = uWindDir;
        #endif
        float npdPhase = npdTreeOrigin.x * 0.13 + npdTreeOrigin.z * 0.097;
        float npdT = uTime * 1.45 + npdPhase;
        /* Two waves an octave and a half apart, so the belt never comes
           back into step with itself the way a single sine does. */
        float npdGust = sin(npdT) * 0.62 + sin(npdT * 2.37 + 1.7) * 0.38;
        transformed.xz += npdLocalWind * (npdGust * aSway * uWindStrength);`,
      );
  };
  material.customProgramCacheKey = () => "npd-tree-wind";
  material.userData.windUniforms = uniforms;

  return { material, uniforms };
}

export function createTrees(options: TreeOptions): TreesResult {
  const { zones, worldSize, seed, avoidRadius = 26 } = options;
  const total = zones.reduce((sum, zone) => sum + zone.count, 0);

  const { geometry } = buildConifer(
    options.canopyColor,
    options.canopyLitColor,
    options.trunkColor,
  );
  const { material, uniforms } = createTreeMaterial();

  /**
   * The trail, rasterised into a coarse occupancy grid once, so the
   * per-candidate test is a single array lookup.
   *
   * The alternative is a distance check against six hundred spline points
   * for every one of the ~100k candidates rejection sampling gets through,
   * which is sixty million square roots to decide where some trees go.
   */
  const gridSize = 128;
  const cell = worldSize / gridSize;
  const blocked = new Uint8Array(gridSize * gridSize);
  if (options.avoid) {
    const reach = Math.ceil(avoidRadius / cell);
    for (const point of options.avoid) {
      const cx = Math.floor((point.x + worldSize / 2) / cell);
      const cz = Math.floor((point.z + worldSize / 2) / cell);
      for (let dz = -reach; dz <= reach; dz++) {
        for (let dx = -reach; dx <= reach; dx++) {
          const gx = cx + dx;
          const gz = cz + dz;
          if (gx < 0 || gz < 0 || gx >= gridSize || gz >= gridSize) continue;
          if (dx * dx + dz * dz > reach * reach) continue;
          blocked[gz * gridSize + gx] = 1;
        }
      }
    }
  }

  const random = mulberry32(seed);
  const matrix = new THREE.Matrix4();
  const position = new THREE.Vector3();
  const quaternion = new THREE.Quaternion();
  const scale = new THREE.Vector3();
  const normal = new THREE.Vector3();
  const up = new THREE.Vector3(0, 1, 0);

  const mesh = new THREE.InstancedMesh(geometry, material, total);
  mesh.instanceMatrix.setUsage(THREE.StaticDrawUsage);

  let planted = 0;
  const plantedPerZone: number[] = [];

  for (let z0 = 0; z0 < zones.length; z0++) {
    const zone = zones[z0];
    const {
      sampler,
      innerRadius,
      outerRadius,
      count,
      heightOffset = 0,
      treelineHeight,
      minPlantingHeight = 0.5,
      minSlope = 0.74,
      groveScale = 74,
      groveThreshold = 0.42,
      minSize = 8,
      maxSize = 13.5,
    } = zone;

    const fadeStart = treelineHeight * 0.8;
    const zoneStart = planted;
    // Each zone gets its own noise stream, so the far rings do not inherit
    // the near one's grove pattern at a different radius - which the eye
    // picks up as concentric banding even when it cannot say what it is.
    const zoneSeed = (seed + z0 * 0x9e37) | 0;

    // Rejection sampling needs a ceiling or a treeline set below the
    // terrain turns this into an infinite loop at boot with nothing on
    // screen to say why. The far zones are mostly clearing by design, so
    // their accept rate is low and the ceiling has to be generous.
    const maxAttempts = count * 60;

    for (let attempt = 0; attempt < maxAttempts && planted - zoneStart < count; attempt++) {
      // sqrt between the two radii, not on the outer alone: uniform r
      // packs area into the inner edge of a ring the same way it packs a
      // disc into its middle, and on the wide outer zones that difference
      // is the whole plain being bare while its rim is a hedge.
      const t = random();
      const radius = Math.sqrt(
        innerRadius * innerRadius + t * (outerRadius * outerRadius - innerRadius * innerRadius),
      );
      const angle = random() * Math.PI * 2;
      const x = Math.cos(angle) * radius;
      const z = Math.sin(angle) * radius;

      const gx = Math.floor((x + worldSize / 2) / cell);
      const gz = Math.floor((z + worldSize / 2) / cell);
      if (gx >= 0 && gz >= 0 && gx < gridSize && gz < gridSize && blocked[gz * gridSize + gx]) {
        continue;
      }

      const y = sampler.heightAt(x, z) + heightOffset;
      if (y < minPlantingHeight || y > treelineHeight) continue;

      sampler.normalAt(x, z, undefined, normal);
      if (normal.y < minSlope) continue;

      // Thin out toward the treeline rather than stopping at it.
      if (y > fadeStart) {
        const climb = (y - fadeStart) / (treelineHeight - fadeStart);
        if (random() < climb * climb) continue;
      }

      // Groves. The threshold is what leaves clearings between them.
      if (groveNoise(x / groveScale, z / groveScale, zoneSeed) < groveThreshold) continue;

      // Trees grow plumb, not perpendicular to the slope - and they get
      // shorter and scrubbier as the air thins, which is most of what
      // makes a treeline look like a treeline rather than a crop line.
      const altitude = Math.min(1, Math.max(0, y / treelineHeight));
      const size = (minSize + random() * (maxSize - minSize)) * (1 - altitude * 0.42);
      scale.set(size * (0.82 + random() * 0.36), size, size * (0.82 + random() * 0.36));
      quaternion.setFromAxisAngle(up, random() * Math.PI * 2);
      // Sunk a couple of percent of its own height: a flat-bottomed trunk
      // on a slope leaves a sliver of daylight under its uphill side
      // otherwise, and scaling the sink with the tree keeps that true for
      // the big ones in the valley and the scrub near the treeline alike.
      position.set(x, y - size * 0.02, z);

      matrix.compose(position, quaternion, scale);
      mesh.setMatrixAt(planted, matrix);
      planted++;
    }

    plantedPerZone.push(planted - zoneStart);
  }

  // The tail of the buffer is whatever Matrix4 left there - an identity
  // matrix, which would park a stack of unit-scale trees at the origin,
  // inside the mountain, casting nothing and visible from below. Telling
  // the mesh how many are real is what retires them.
  mesh.count = planted;
  mesh.instanceMatrix.needsUpdate = true;
  mesh.computeBoundingSphere();

  mesh.castShadow = false;
  mesh.receiveShadow = options.receiveShadow ?? false;

  return {
    mesh,
    planted,
    plantedPerZone,
    update: (time: number) => {
      uniforms.uTime.value = time;
    },
    setWindDirection: (x: number, z: number) => {
      uniforms.uWindDir.value.set(x, z);
      // A zero-length direction would normalize to NaN and take every tree
      // in the belt with it.
      if (uniforms.uWindDir.value.lengthSq() > 1e-8) uniforms.uWindDir.value.normalize();
      else uniforms.uWindDir.value.set(1, 0);
    },
  };
}
