import * as THREE from "three";
import { createRenderer } from "./renderer";
import { createTerrain, type TerrainResult } from "./terrain";
import { createTrail, type TrailResult } from "./trail";
import { createCameraRig, type CameraRig } from "./camera-rig";
import { detectCapabilities, type GpuCapabilities } from "./capabilities";
import { createTerrainMaterial } from "./materials/terrain.glsl";
import { createSkyRig, type SkyRig } from "./sky";
import { createTrees, type TreesResult } from "./trees";
import { createParticleFog, type ParticleFogRig } from "./particle-fog";
import { loadTerrainTextures } from "./textures";
import { generateHorizonHeightmap } from "./horizon-heightmap";
import type { HeightmapBundle } from "./heightmap-store";
import {
  HEIGHTMAP_SEED,
  HORIZON_MAX_HEIGHT,
  HORIZON_SEGMENTS,
  HORIZON_SIZE,
  MASSIF_SEGMENTS,
  MAX_HEIGHT,
  WORLD_SIZE,
  horizonHeightmapOptions,
} from "./heightmap-presets";
// Snow starts high. The old 0.44 put it over most of the massif, which was
// survivable when the rock beneath was Pearl and the two nearly matched -
// with Stone Slate rock it just buried the mountain in white and threw away
// the rock/snow contrast the mark is built on. The mark caps its peaks, it
// does not blanket them.
const SNOWLINE = MAX_HEIGHT * 0.6;

/**
 * Where the conifer belt gives out, and where the ground stops being
 * green - one number, deliberately, driving both.
 *
 * The shader's treeline and the trees' own treeline have to be the same
 * height or the belt ends somewhere the heath under it does not, and the
 * eye reads that instantly as trees standing on bare rock. Both take it
 * from here. 0.3 puts it a little under a third of the way up, which
 * leaves the whole middle of the massif - the part the camera cranes past
 * and the part the switchbacks are drawn on - as rock and scree.
 */
const TREELINE = MAX_HEIGHT * 0.3;

/**
 * Reads a scene colour from the design tokens, so the mountain repaints with
 * the theme instead of carrying a second, private palette that has to be
 * kept in sync with tokens.css by hand.
 *
 * The dev-only guard is not decoration. `getPropertyValue("#a3927c")` does
 * not throw - it returns "", so the fallback silently becomes the real
 * colour and the call looks like it works. That is exactly how the rock and
 * snow colours previously ended up hard-coded (and swapped) here while
 * still appearing to read from tokens.
 */
function cssColor(varName: string, fallback: string): THREE.Color {
  if (import.meta.env.DEV && !varName.startsWith("--")) {
    console.warn(
      `cssColor("${varName}") is not a custom property name - this always falls back. Did you mean a --token?`,
    );
  }
  const value = getComputedStyle(document.documentElement)
    .getPropertyValue(varName)
    .trim();
  return new THREE.Color(value || fallback);
}

export interface SceneHandle {
  scene: THREE.Scene;
  camera: THREE.PerspectiveCamera;
  renderer: THREE.WebGLRenderer;
  canvas: HTMLCanvasElement;
  terrain: TerrainResult;
  worldSize: number;
  maxHeight: number;
  /**
   * Built on every page, not just the climb.
   *
   * This scene now outlives the page it booted on - the router swaps <main>
   * underneath it and the canvas is never torn down - so whichever route
   * happens to be showing when it starts says nothing about which routes it
   * will have to serve. Building the trail lazily on first arrival at the
   * homepage would mean generating a 600-sample spline mid-cross-fade.
   */
  trail: TrailResult;
  /** The conifer belt - one InstancedMesh, planted once at boot. */
  trees: TreesResult;
  /**
   * The drifting mist banks. `particleFog.config` is live, the same
   * way `sky.config` is - see scene/particle-fog.config.ts.
   */
  particleFog: ParticleFogRig | null;
  cameraRig: CameraRig;
  /**
   * The sky, the sun and everything the sun decides. `sky.config` is live -
   * writing to it from the console or from ?sky re-lights the scene on the
   * next frame, which is the only practical way to tune an atmosphere.
   */
  sky: SkyRig;
  /**
   * Whether the climb is the thing on screen. False walks the drawn trail -
   * and the camera's lateral drift with it - back to where the page opens;
   * true hands control back to the scroll rig. This is what a route change
   * does to the mountain.
   */
  setClimbing: (climbing: boolean, returnMs?: number) => void;
  /**
   * Resolves once the scene has actually put pixels on screen - which is
   * also when shader compilation is done, and therefore the only honest
   * moment to take the boot gate down. See src/ui/boot.ts.
   */
  firstFrame: Promise<void>;
  /** Stops the render loop and frees GPU resources. Also runs automatically on pagehide. */
  dispose: () => void;
}

/**
 * Boots the terrain scene with a static camera framing the whole mountain.
 * Returns null when WebGL2 is unavailable or the visitor prefers reduced
 * motion - callers should leave the CSS fallback in place in that case.
 *
 * Called exactly once per session. The canvas it appends to <body> sits
 * outside the <main> the router replaces, so the mountain is continuous
 * across every route change - see setClimbing() for what a route change
 * actually does to it.
 *
 * Accepts a capability probe from the caller rather than running its own -
 * main.ts already has to run one before deciding whether this module is
 * even worth fetching, and re-running it here would open a second throwaway
 * WebGL context for no reason.
 */
export function initScene(
  capabilities: GpuCapabilities = detectCapabilities(),
  baked: HeightmapBundle = new Map(),
): SceneHandle | null {
  if (!capabilities.webgl2) return null;

  const searchParams = new URLSearchParams(window.location.search);

  /**
   * ?tier=low / ?tier=high forces the quality tier, whatever the probe
   * said.
   *
   * Needed because the tier decision is almost impossible to exercise
   * honestly otherwise. A headless browser reports SwiftShader and is
   * therefore always the LOW tier - so every screenshot taken of this
   * scene, including every one used to judge it, shows the mobile path
   * with half the terrain resolution, no shadows, no detail bump and a
   * third of the trees. The reverse case is worse: nobody can see the
   * mobile path on the machine they are tuning it on without unplugging
   * their GPU.
   *
   * It only ever overrides downward-safe things (mesh density, shadows,
   * bump, tree count) - forcing high on hardware that cannot take it is
   * slow, not broken.
   */
  const forcedTier = searchParams.get("tier");
  const lowTier =
    forcedTier === "low" ||
    (forcedTier !== "high" && (capabilities.isMobile || capabilities.isSoftwareRenderer));
  const tier = lowTier ? "low" : "high";

  const setup = createRenderer({ maxDpr: capabilities.isMobile ? 1.5 : 2 });
  if (!setup) return null;

  const { renderer, canvas } = setup;
  document.body.appendChild(canvas);

  // Set here rather than in the sky rig, and before any material is built:
  // whether shadows exist at all is compiled into every program in the
  // scene, so flipping it after the first render means re-linking all of
  // them. Which shadow, and how strong, stays tunable at runtime; whether
  // there is a shadow map at all is decided once, here.
  //
  // PCF, not VSM. VSM is the one that would give a mountain-sized shadow a
  // genuinely soft edge, but it bleeds light through thin occluders and
  // forces every receiver to cast - on a height field that both casts and
  // receives, that is the artefact there is no hiding. (PCFSoftShadowMap is
  // not an option either: three 0.185 deprecated it and silently downgrades
  // it to this.) The softness here comes from the terrain's own normals
  // instead, which is where it comes from on a real mountainside anyway.
  renderer.shadowMap.enabled = !lowTier;
  renderer.shadowMap.type = THREE.PCFShadowMap;

  const scene = new THREE.Scene();
  const inkColor = cssColor("--terrain-ground", "#0f1a2b");
  renderer.setClearColor(inkColor, 1);
  // Do NOT tune the fog here. Neither of these two numbers survives the
  // first frame: sky.update() overwrites scene.fog.color and .density
  // every frame from SKY_DEFAULTS in scene/sky.ts, which is where the
  // knobs actually live (fogDensity, fogSkyPitch, fogBrightness,
  // fogFollowsSky) and where ?sky's sliders write. All this call does is
  // put a FogExp2 on the scene before any material compiles - fog is a
  // shader define, so a scene that gains fog later has to re-link every
  // program in it - and give the frames before the sky's first update a
  // colour that is at least the right ballpark.
  scene.fog = new THREE.FogExp2(inkColor.getHex(), 0.0009);

  // The 38 here only covers the frames before the rig's first update() and
  // ?debug's orbit mode - during the climb the lens belongs to the shots in
  // camera-rig.ts, which set it every frame.
  const camera = new THREE.PerspectiveCamera(
    38,
    window.innerWidth / window.innerHeight,
    1,
    3000,
  );
  camera.position.set(0, MAX_HEIGHT * 0.95, WORLD_SIZE * 1.0);
  camera.lookAt(0, MAX_HEIGHT * 0.42, 0);

  // The massif is the logo in three dimensions, so it is built from the
  // mark's own three values: Stone Slate rock against the North Navy sky it
  // is already fogged into, capped in North Mist. (These were previously
  // swapped - rock Pearl, snow Warm Stone - which put a white mountain under
  // brown snow, neither of which is how the mark is drawn.)
  const rockColor = cssColor("--terrain-rock", "#4b5563");
  const snowColor = cssColor("--terrain-snow", "#eef3fb");
  const screeColor = cssColor("--terrain-scree", "#5a5b57");
  const tundraColor = cssColor("--terrain-tundra", "#4f5a4c");

  // Started before any mesh is built, so the download overlaps the
  // heightmap decode and the first shader compile rather than following
  // them. Every terrain material holds the texture object from the moment
  // it is created; three fills it in when the bytes land. `ready` is what
  // the boot gate waits on - see firstFrame.
  const textures = loadTerrainTextures(renderer, { anisotropy: lowTier ? 2 : 4 });

  /**
   * Everything about the surface that is the same on all three terrains:
   * the grain map, the two band edges between the four surfaces, and how
   * much of the detail bump this tier can afford.
   *
   * Shared rather than repeated because the massif and the apron MUST
   * agree. The massif's heightmap falls off to zero well inside its own
   * mesh, so it ends in a wide flat skirt that butts against the apron -
   * and if the two disagree about what a flat surface at y=0 is made of,
   * that skirt's square edge is drawn across the scene as a hard diagonal.
   * That is the same constraint --terrain-plain was written for; it now
   * covers the treeline too.
   */
  const surface = {
    detailMap: textures.detail,
    screeColor,
    tundraColor,
    treelineHeight: TREELINE,
    // The detail bump is four screen-space derivative pairs per fragment
    // over a full-screen mountain. It is the single most skippable thing
    // in this shader and the low tier skips it.
    detailBump: lowTier ? 0 : 0.38,
    // Both ends as fractions of the world, not as absolutes: the camera
    // stands 0.5-0.64 of a world back from the summit axis, so a fade
    // written in world units would mean something different the moment
    // WORLD_SIZE moved.
    detailBumpFadeNear: WORLD_SIZE * 0.16,
    detailBumpFadeFar: WORLD_SIZE * 0.62,
    // One tile every 120 units, so the map lays down about five repeats
    // across the massif. Tighter than that and the strata in the rock
    // channel start reading as a pattern rather than as rock.
    detailTileSize: 120,
  };

  // Full resolution on desktop-class hardware; halved for mobile and for
  // renderers that report a software/low-tier context (e.g. SwiftShader),
  // since that's a much better fill-rate/vertex-count trade there.
  const massifSegments = MASSIF_SEGMENTS[tier];
  const terrain = createTerrain({
    width: WORLD_SIZE,
    depth: WORLD_SIZE,
    segments: massifSegments,
    maxHeight: MAX_HEIGHT,
    seed: HEIGHTMAP_SEED,
    rockColor,
    snowColor,
    snowlineHeight: SNOWLINE,
    surface,
    // Baked by `npm run bake` and fetched before this runs. Absent, this
    // generates the same map from the same seed - a slower first paint,
    // not a different mountain. See heightmap-store.ts.
    heightmap: baked.get(`massif-${massifSegments + 1}`),
  });
  scene.add(terrain.mesh);

  // A single flat apron beneath the massif. Keeping this as one plane avoids
  // a second displaced height field intersecting the mountain at its rim.
  // 24x, not 6x. At 6x the plane's own far edge landed only ~95% fogged out,
  // which is invisible against a navy sky but draws a hard diagonal seam
  // across a mist one. Pushing the rim past the point where exp2 fog is
  // fully saturated retires the seam in both themes; it is still two
  // triangles either way.
  const groundGeometry = new THREE.PlaneGeometry(WORLD_SIZE * 24, WORLD_SIZE * 24, 1, 1);
  groundGeometry.rotateX(-Math.PI / 2);
  // Its own colour, not the massif's rock. This plane is 6x the world size,
  // so whatever it is painted lands across the whole lower viewport behind
  // the copy - as rock it read as a lit slab, and in day mode (navy rock)
  // it blacked out the bottom half of the page under navy text. Painted the
  // fog colour it dissolves into the horizon and reads as distance.
  const plainColor = cssColor("--terrain-plain", "#0f1a2b");
  const groundMaterial = createTerrainMaterial({
    ...surface,
    rockColor: plainColor,
    snowColor,
    // Keep the plain below the snowline so it uses only the rock portion of
    // the terrain shader while still sharing its lighting/detail treatment.
    snowlineHeight: MAX_HEIGHT * 2,
    // The apron is one flat quad two triangles across, so a bump derived
    // from screen-space derivatives has nothing to hold on to here - the
    // whole plane shares one geometric normal and the grain would be the
    // only thing in it, which reads as crawling static rather than ground.
    detailBump: 0,
    // Its tile is stretched well out, because this plane is 24x the world
    // and the massif's tile repeated across it would be a visible grid the
    // massif's own macro variation cannot break up at that scale.
    detailTileSize: 260,
    macroScale: 1400,
  });
  const ground = new THREE.Mesh(groundGeometry, groundMaterial);
  ground.position.y = -0.5;
  scene.add(ground);

  // The far range, closing the edge of the plain.
  //
  // It is the same thing the massif is - a heightmap displacing a plane,
  // through the same material - and that is the point: rock, snowline and
  // lighting all come out matched without a second set of numbers to keep
  // in step. Only the map differs, and only in its mask: the massif's
  // falls off to nothing at its own edge, this one is nothing in the
  // middle and rises at the rim. See horizon-heightmap.ts.
  //
  // It sits just under the apron so the flat middle of its grid - the part
  // that is only there because a heightmap is a square - is hidden beneath
  // the ground plane instead of z-fighting with it. The peaks come up
  // through that plane, which is what the apron is for anyway.
  const horizonSegments = HORIZON_SEGMENTS[tier];
  const horizonResolution = horizonSegments + 1;
  const horizon = createTerrain({
    width: HORIZON_SIZE,
    depth: HORIZON_SIZE,
    segments: horizonSegments,
    maxHeight: HORIZON_MAX_HEIGHT,
    seed: HEIGHTMAP_SEED,
    rockColor,
    snowColor,
    // Proportionally much higher than the massif's 0.6. These peaks are
    // over twice as tall, so the same fraction caps the entire range - and
    // a solid white skyline is exactly what the near peak's own caps have
    // to stand out against. At 0.8 only the highest of them carry snow and
    // the rest read as rock, which is also how a real range looks from a
    // summit: one or two white tops in a lot of grey.
    snowlineHeight: HORIZON_MAX_HEIGHT * 0.8,
    surface: {
      ...surface,
      // No bump and a coarser tile: this range is four to eight times
      // further off than the massif and mostly fogged, so every one of
      // those fragments would be spending derivative work on detail that
      // arrives already greyed out.
      detailBump: 0,
      detailTileSize: 220,
      macroScale: 900,
    },
    heightmap:
      baked.get(`horizon-${horizonResolution}`) ??
      generateHorizonHeightmap(horizonHeightmapOptions(horizonResolution)),
  });
  horizon.mesh.position.y = -0.6;
  // Outside the sun's shadow camera by design - see sky.ts. Pulling that
  // frustum out to cover a 3200-unit grid would spend the map on terrain
  // nobody can resolve and leave the massif, the one thing the shadow is
  // for, a few texels wide.
  horizon.mesh.receiveShadow = false;
  scene.add(horizon.mesh);

  // The massif throws the shadow and the massif also catches it - the flat
  // apron only ever receives. Self-shadowing a displaced height field is
  // what makes a ridge read as a ridge once the sun is off to one side;
  // without it the whole flank is lit by dot(n, l) alone and the gullies
  // behind a spur come out as bright as the spur.
  //
  // The trail is deliberately not a caster. It is a tube a few units across
  // draped on the surface it would be shadowing, so all it can contribute
  // is a dashed line of shadow-map acne under itself.
  terrain.mesh.castShadow = true;
  terrain.mesh.receiveShadow = true;
  ground.receiveShadow = true;

  // Lighting used to be two fixed lights and a hand-picked fog colour: a
  // cool North Mist key, a Warm Stone hemisphere, navy fog. All three are
  // now downstream of where the sun is, because the sun moves - see
  // scene/sky.ts. What the palette still owns is everything the light falls
  // *on*: rock, snow, trail, flag.
  const groundColor = cssColor("--terrain-ground", "#0f1a2b");

  function resize() {
    const w = window.innerWidth;
    const h = window.innerHeight;
    renderer.setSize(w, h);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  }
  window.addEventListener("resize", resize);

  let controls: { update: () => void } | undefined;
  let stats: { dom: HTMLElement; update: () => void } | undefined;

  // searchParams is parsed up by the tier decision, which needs it first.
  const debug = searchParams.has("debug");

  // Built unconditionally now. The trail used to be gated on the landing
  // page having rendered a .summit section, which was the right test while
  // every route change was a fresh document - but the scene now persists
  // across route changes, so the page that happens to be on screen at boot
  // no longer tells us anything about the pages this scene will serve.
  //
  // The climb line is the mark's rising arrow, so it is the one warm thing
  // on a cool mountain: shadowed Warm Stone behind the climber, lit Warm
  // Stone behind them, Pearl at the drawing head. (--trail and
  // --trail-finish were literal #ff0000 / #00ff00 debug values before -
  // the two colours furthest from this palette that exist.)
  const trail = createTrail({
    worldSize: WORLD_SIZE,
    maxHeight: MAX_HEIGHT,
    sampler: terrain.sampler,
    brandColor: cssColor("--trail", "#8a7a63"),
    brandLitColor: cssColor("--trail-finish", "#c9b795"),
    tipColor: cssColor("--trail-tip", "#f7f5f2"),
    structureColor: cssColor("--structure", "#4b5563"),
    flagColor: cssColor("--flag", "#c8372c"),
    flagLitColor: cssColor("--flag-lit", "#ff6a52"),
  });
  scene.add(trail.group);

  // The conifer belt, planted after the trail because it plants around it:
  // trail.controlPoints is handed over as a keep-out, so no tree ends up
  // standing on a switchback the page is about.
  //
  // Three rings, one mesh, one draw call.
  //
  // The massif's own belt was the whole forest to begin with, and it
  // stopped dead at the edge of the massif - which left every shot with a
  // wooded mountain standing in the middle of a bare plain that ran all
  // the way to the skyline. The two outer rings are that plain and the
  // foothills behind it, planted far more thinly and in much broader
  // stands, so the distance reads as country rather than as ground.
  //
  // The outer two are planted from the FAR RANGE's sampler, not the
  // massif's, because that is the surface out there - and they carry its
  // mesh offset, since a sampler describes a heightmap and not where the
  // mesh holding it was put. Inside about 645 units the far range is flat
  // and sits just under the apron, so those trees read as standing on the
  // apron; past that they climb the foothills it raises.
  //
  // Counts are the one thing that changes by tier. This is not a fill-rate
  // decision - the trees are a few pixels each - it is a vertex-throughput
  // one, which is the budget a phone runs out of first. At 34 triangles a
  // tree the low tier's whole belt is about 97k triangles, well under what
  // the half-resolution massif beneath it already costs.
  const PLAIN_INNER = WORLD_SIZE * 0.52;
  const PLAIN_OUTER = HORIZON_SIZE * 0.2;
  const FOOTHILL_OUTER = HORIZON_SIZE * 0.37;
  const HORIZON_MESH_Y = -0.6;

  const trees = createTrees({
    worldSize: WORLD_SIZE,
    seed: HEIGHTMAP_SEED ^ 0x7e1f2,
    avoid: trail.controlPoints,
    canopyColor: cssColor("--tree-canopy", "#2f3f36"),
    canopyLitColor: cssColor("--tree-canopy-lit", "#6d7f63"),
    trunkColor: cssColor("--tree-trunk", "#3d3830"),
    // Same bargain the shadow map makes everywhere else in this scene:
    // the low tier has no shadow map at all, so asking for receipt there
    // would only compile a sampler nothing writes to.
    receiveShadow: !lowTier,
    zones: [
      {
        // The near belt: the massif's valley and lower flanks.
        sampler: terrain.sampler,
        innerRadius: 0,
        outerRadius: WORLD_SIZE * 0.47,
        count: lowTier ? 1700 : 3200,
        treelineHeight: TREELINE,
      },
      {
        // The plain. Nothing out here has any relief, so the only thing
        // shaping it is the grove noise - hence a scale three times the
        // near belt's and a threshold well above it. That is what turns
        // 900 trees spread over an area four times the massif's into a
        // handful of readable stands instead of an even dusting.
        sampler: horizon.sampler,
        heightOffset: HORIZON_MESH_Y,
        innerRadius: PLAIN_INNER,
        outerRadius: PLAIN_OUTER,
        count: lowTier ? 450 : 900,
        // The apron is a hair above the far range's flat middle, so the
        // ground here samples slightly BELOW zero. A floor of 0.5 - the
        // default, and the right one on the massif - would reject the
        // entire plain and plant nothing at all.
        minPlantingHeight: -5,
        treelineHeight: 6,
        groveScale: 230,
        groveThreshold: 0.56,
        // Bigger than the near belt's, deliberately. At this range a tree
        // at the near belt's size is a dozen pixels of aliasing; the fog
        // has already taken most of its contrast by the time it arrives.
        minSize: 9,
        maxSize: 15.5,
      },
      {
        // The foothills of the far range, where it starts to rise.
        sampler: horizon.sampler,
        heightOffset: HORIZON_MESH_Y,
        innerRadius: PLAIN_OUTER * 0.96,
        outerRadius: FOOTHILL_OUTER,
        count: lowTier ? 700 : 1400,
        // Only the risen ground - below this is plain, and the ring above
        // has already planted it.
        minPlantingHeight: 1,
        treelineHeight: HORIZON_MAX_HEIGHT * 0.34,
        groveScale: 300,
        groveThreshold: 0.5,
        // The far range is steeper than the massif at the same height, so
        // holding it to the massif's slope test would leave the foothills
        // bare and put the whole ring in the few flat gullies.
        minSlope: 0.66,
        minSize: 11,
        maxSize: 19,
      },
    ],
  });
  scene.add(trees.mesh);
  if (import.meta.env.DEV) {
    console.log(
      `[trees] planted ${trees.planted} - massif/plain/foothills ${trees.plantedPerZone.join("/")}`,
    );
  }

  // The control points are no longer flown - the camera holds one shot and
  // only drifts sideways with scroll. They are handed over so the rig can
  // average them and stand on the flank the climb is actually drawn on,
  // which is the whole point of a fixed shot: the line and the flag have to
  // be facing the viewer for the length of the page.
  const cameraRig = createCameraRig({
    camera,
    controlPoints: trail.controlPoints,
    worldSize: WORLD_SIZE,
    maxHeight: MAX_HEIGHT,
    sampler: terrain.sampler,
  });

  // Built after the camera rig because it takes its bearing from the rig's
  // flank: the sun rises a quarter turn off the camera's axis and sets a
  // quarter turn off it on the other side, so the shadow the massif throws
  // is always across the frame rather than straight toward or away from the
  // lens. Both of those hide it - toward, and the mountain stands in its
  // own shadow; away, and the shadow is behind the mountain.
  const flankBearing = THREE.MathUtils.radToDeg(
    Math.atan2(cameraRig.flank.x, cameraRig.flank.y),
  );

  // The wind blows across the flank the camera stands on, not along it.
  // Along it, every tree sways toward or away from the lens, which at this
  // distance is a change in silhouette of well under a pixel; across it,
  // the same motion is lateral and the belt visibly breathes.
  trees.setWindDirection(-cameraRig.flank.y, cameraRig.flank.x);

  // The mist banks. ?mist=off drops them entirely, which is both how the
  // scene gets judged without them and how their fill-rate cost gets
  // measured - they are the one thing here that is paid for in blended
  // fragments rather than in vertices, so a frame-time difference with
  // and against is the only honest number.
  //
  // Same bearing the conifers just took, for the obvious reason: mist
  // drifting one way over trees leaning the other is not weather.
  const particleFog =
    searchParams.get("mist") === "off"
      ? null
      : createParticleFog({
          scene,
          color: cssColor("--scene-mist", "#253449"),
          lowTier,
          seed: HEIGHTMAP_SEED ^ 0x4d157,
        });
  if (particleFog) {
    particleFog.setWindDirection(-cameraRig.flank.y, cameraRig.flank.x);
    scene.add(particleFog.mesh);
  }

  const sky = createSkyRig({
    scene,
    camera,
    worldSize: WORLD_SIZE,
    groundColor,
    // A 2M-triangle caster re-rendered into a shadow map is the single most
    // expensive thing this scene could ask a phone for, and the low-tier
    // path is already running half the terrain resolution to stay afloat.
    shadows: !lowTier,
    // +90 is a quarter turn off the camera's axis, which in this bearing
    // convention (from +Z toward +X, and the camera looking along -flank)
    // is screen RIGHT - decreasing the offset swings the sun toward screen
    // left. +45 is that quarter turn rotated 45 degrees left, so the sun
    // now sits off the camera's left shoulder and the massif throws its
    // shadow across the frame to the right.
    //
    // Still an offset from the flank rather than a fixed bearing, for the
    // reason the flank is derived at all: a hard-coded number here would
    // go on pointing at the old side the first time the trail is retuned,
    // and the shadow would end up behind the mountain where nobody can
    // see it.
    config: { azimuth: flankBearing + 155 },
  });

  // Leaving the climb is the one camera move with no scroll position behind
  // it, so it runs on its own clock. Camera and trail are driven from a
  // single eased value rather than tweened separately: the line retracts as
  // the camera drifts back, which reads as one move back down to base camp
  // instead of two things that happen to animate at the same time.
  let descent: { from: number; startedAt: number; ms: number } | null = null;

  const setClimbing = (climbing: boolean, returnMs = 900) => {
    if (climbing) {
      // Scroll owns progress again from here.
      descent = null;
      return;
    }

    // A leave is announced twice - once when the navigation is committed,
    // once when the destination confirms it is not the climb - and the
    // second call must not restart the ease from wherever the first one has
    // got to. That restart is visible: the curve drops back to zero velocity
    // mid-descent and the camera hitches.
    if (descent) return;

    const from = cameraRig.currentProgress();
    if (from <= 1e-4) {
      // Already at base camp. Nothing to walk back, and starting a tween
      // here would only give a scroll rig mounting on top of it something
      // to fight over the next few frames.
      cameraRig.jumpTo(0);
      trail.setProgress(0);
      return;
    }
    descent = { from, startedAt: performance.now(), ms: returnMs };
  };

  const advanceDescent = () => {
    if (!descent) return;
    const k = Math.min(1, (performance.now() - descent.startedAt) / descent.ms);
    // easeInOutCubic. The return has to start and finish at a standstill or
    // it reads as the camera being yanked rather than walking back down.
    const eased = k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2;
    const progress = descent.from * (1 - eased);
    // jumpTo, not setProgress: this is already an eased curve, and putting
    // the rig damping on top of it would flatten the ease-out into a crawl.
    cameraRig.jumpTo(progress);
    trail.setProgress(progress);
    if (k >= 1) descent = null;
  };

  // ?camera opens the framing panel: sliders for the height, vertical angle
  // and zoom at each end of the crane, wired straight into rig.shots, plus a
  // progress scrub so the summit end can be judged without scrolling there.
  // Unlike ?debug it leaves the rig driving, because the point is to tune
  // the move the visitor actually gets. Dynamic import, so none of it is in
  // the bundle anyone else downloads.
  if (searchParams.has("camera")) {
    void import("./camera-tuner").then(({ createCameraTuner }) => {
      createCameraTuner({
        rig: cameraRig,
        worldSize: WORLD_SIZE,
        maxHeight: MAX_HEIGHT,
        setTrailProgress: trail.setProgress,
      });
    });
  }

  // ?sky opens the atmosphere panel: the sun's arc, the Preetham knobs, the
  // clouds, and what the sun does to the light, the fog and the shadow.
  // Same bargain as ?camera - none of these numbers can be judged except by
  // dragging them against the real render, and none of the panel is in the
  // bundle anyone else downloads.
  if (searchParams.has("sky")) {
    void import("./sky-tuner").then(({ createSkyTuner }) => {
      createSkyTuner({
        rig: sky,
        // The sun is downstream of the camera rig, so the scrub drives the
        // climb and lets the sun follow - which is also the only way to see
        // the traverse itself rather than one elevation at a time.
        setProgress: (t) => {
          cameraRig.jumpTo(t);
          trail.setProgress(t);
        },
      });
    });
  }

  // ?debug frees the camera with OrbitControls to inspect the raw terrain -
  // it owns the camera itself, so it takes over from the climb rig entirely.
  if (debug) {
    canvas.style.pointerEvents = "auto";
    // Proves the sampler and the mesh are the same surface before anyone
    // starts blaming an offset for a floating line.
    terrain.sampler.verifyAgainstMesh(terrain.mesh);
    trail.setProgress(1);
    void Promise.all([
      import("three/examples/jsm/controls/OrbitControls.js"),
      import("three/examples/jsm/libs/stats.module.js"),
    ]).then(([{ OrbitControls }, StatsModule]) => {
      const orbit = new OrbitControls(camera, canvas);
      orbit.target.set(0, MAX_HEIGHT * 0.42, 0);
      orbit.enableDamping = true;
      orbit.update();
      controls = orbit;

      const StatsCtor = StatsModule.default;
      const statsPanel = new StatsCtor();
      statsPanel.dom.style.position = "fixed";
      statsPanel.dom.style.zIndex = "var(--z-overlay)";
      document.body.appendChild(statsPanel.dom);
      stats = statsPanel;
    });
  }

  // Resolved from inside the loop rather than out here, because "the scene
  // is constructed" and "the scene is on screen" are separated by the frame
  // that compiles every shader in it - and that frame is what the boot gate
  // is actually waiting on.
  let framesRendered = 0;
  let markFirstFrame: (() => void) | undefined;
  const framesPainted = new Promise<void>((resolve) => {
    markFirstFrame = resolve;
  });

  // The grain map is in here too, not just the frames.
  //
  // Two frames used to be the whole test, because the only thing that
  // could still change under the visitor after them was nothing. Now the
  // terrain's surfaces arrive over the network: taking the gate down at
  // frame two would show a mountain in flat token colours and then repaint
  // every slope on it a moment later, which is precisely the "visibly
  // change under the visitor a moment after they started reading" this
  // gate exists to prevent. `ready` resolves on failure as well as on
  // success, so a 404 costs a plainer mountain and not a gate that never
  // lifts.
  const firstFrame = Promise.all([framesPainted, textures.ready]).then(() => undefined);

  // The flags' wind and pop springs run on wall-clock time, not on scroll
  // position, so the loop has to hand them a real delta. Kept by hand rather
  // than with THREE.Clock, which is deprecated in three 0.185.
  let lastFrameAt = performance.now();
  // Seconds since boot, for the cloud drift. Measured from here rather than
  // passed performance.now() directly: the shader multiplies it into a
  // noise coordinate, and a number that starts in the millions has already
  // spent most of its float precision before the clouds get any.
  const startedAt = lastFrameAt;

  renderer.setAnimationLoop(() => {
    const now = performance.now();
    const dt = (now - lastFrameAt) / 1000;
    lastFrameAt = now;
    if (!debug) {
      advanceDescent();
      cameraRig.update();
    }
    controls?.update();
    // After whichever of the two just moved the camera - the flags turn to
    // face it, so they need this frame's position, not last frame's.
    trail.updateFlags(camera, dt);
    // Wall-clock, like the flags - the belt goes on moving while the page
    // is still, which is what stops a scroll-driven scene reading as a
    // paused video whenever the visitor stops scrolling.
    trees.update((now - startedAt) / 1000);
    // After the sky's own update would be tidier, but the mist reads
    // scene.fog.color and the sky writes it - so a frame's lag either way
    // is the choice, and lagging the mist by a frame is invisible where
    // lagging the terrain's own fog is not.
    particleFog?.update((now - startedAt) / 1000);

    // The sun is read off the camera's own damped progress rather than
    // being wired to the scroll trigger. Everything that moves the climb
    // already goes through the rig - scroll, the walk back down to base
    // camp on a route change, the ?camera scrub - so taking the position
    // from the rig is what makes the sun follow all three rather than only
    // the first, and it inherits the same damping, so the sun does not snap
    // when scroll does. After the camera for the same reason the flags are:
    // the sky box is re-centred on it, and the fog colour is sampled along
    // the direction it is facing.
    sky.setProgress(cameraRig.currentProgress());
    sky.update((now - startedAt) / 1000);


    renderer.render(scene, camera);
    stats?.update();

    // The second frame, not the first: the first render is the one that
    // blocks on shader compilation, so it has been submitted but not
    // necessarily composited by the time it returns.
    if (++framesRendered === 2) markFirstFrame?.();
  });

  const dispose = () => {
    renderer.setAnimationLoop(null);
    window.removeEventListener("resize", resize);
    scene.traverse((obj) => {
      const mesh = obj as Partial<THREE.Mesh>;
      mesh.geometry?.dispose();
      const material = mesh.material;
      if (Array.isArray(material)) material.forEach((m) => m.dispose());
      else material?.dispose();
    });
    // Not reached by the traverse above: the grain map is referenced by a
    // custom uniform, not by material.map, so disposing the materials
    // leaves the GPU texture allocated.
    textures.detail.dispose();
    // Its puff texture is a custom uniform, not material.map, so the
    // traverse above does not reach it either.
    particleFog?.dispose();
    renderer.dispose();
  };
  window.addEventListener("pagehide", (event) => {
    // event.persisted means the document is going into the back/forward
    // cache rather than being destroyed - it can come back, and it comes
    // back with this canvas still in the DOM and the CSS fallback already
    // removed. Disposing here would restore the visitor to a dead grey
    // rectangle where the mountain was.
    if (!event.persisted) dispose();
  });

  const handle: SceneHandle = {
    scene,
    camera,
    renderer,
    canvas,
    terrain,
    worldSize: WORLD_SIZE,
    maxHeight: MAX_HEIGHT,
    trail,
    trees,
    particleFog,
    cameraRig,
    sky,
    setClimbing,
    firstFrame,
    dispose,
  };

  // The second half of "expose the sky for tweaking": ?sky is the panel,
  // this is the console. `__npdScene.sky.config.elevation = 120` holds the
  // sun there; the rest of the handle comes along because it costs nothing
  // and the sky is rarely the only thing being looked at.
  //
  // DEV only, and stripped by the bundler rather than guarded at runtime -
  // a global handle to the whole scene graph is a debugging tool, not
  // something to leave in the page that ships.
  if (import.meta.env.DEV) {
    (window as Window & { __npdScene?: SceneHandle }).__npdScene = handle;
  }

  return handle;
}
