import { SimplexNoise2D, boxBlur3x3, fbm } from "./heightmap.ts";

/**
 * The far range: a heightmap shaped like a bowl, flat where the massif and
 * its plain already are and rising into ranges around the rim.
 *
 * Same machinery as the massif - the same seeded simplex, the same ridged
 * multifractal, the same two blur passes - because the far peaks have to
 * look like they were cut from the same rock as the near one. What differs
 * is the mask: the massif's is a radial falloff *to* zero at its edge, and
 * this one is the inverse, zero in the middle and full at the rim. The two
 * therefore never fight over the same ground.
 *
 * Nothing here reads Math.random. Same seed, same range - which is what
 * makes it safe to bake the result to a file and ship that instead.
 */
export interface HorizonHeightmapOptions {
  /** Vertices per side. Should match the horizon mesh's (segments + 1). */
  resolution: number;
  seed: number;
  /**
   * Normalized radius, in units of half the grid width, where the ground
   * starts to rise. Inside this the map is exactly flat, which is the
   * plain the massif stands on.
   */
  innerRadius?: number;
  /** Normalized radius where the ranges reach full height. */
  outerRadius?: number;
  octaves?: number;
  lacunarity?: number;
  gain?: number;
  frequency?: number;
  /**
   * The fraction of full height the rim keeps even where the noise says
   * valley, 0..1.
   *
   * This is what makes it a wall of mountains rather than a scatter of
   * them. At 0 the ridged noise opens gaps right through the range and the
   * empty plain shows between the peaks - which, at the horizon, reads as
   * the world running out.
   */
  baseMass?: number;
  /** How much the range lines are bent out of concentric circles. */
  warpAmount?: number;
  /** Frequency of the slow rise and fall along the range. */
  massFrequency?: number;
}

export function generateHorizonHeightmap(options: HorizonHeightmapOptions): Float32Array {
  const {
    resolution,
    seed,
    innerRadius = 0.4,
    outerRadius = 0.78,
    octaves = 5,
    lacunarity = 2.0,
    gain = 0.5,
    frequency = 2.6,
    baseMass = 0.32,
    warpAmount = 0.3,
    massFrequency = 1.15,
  } = options;

  const noise = new SimplexNoise2D(seed);
  const warpNoise = new SimplexNoise2D((seed ^ 0x9e3779b9) >>> 0);
  const massNoise = new SimplexNoise2D((seed ^ 0x85ebca6b) >>> 0);

  const size = resolution;
  const heights = new Float32Array(size * size);

  let maxAmplitude = 0;
  {
    let amp = 1;
    for (let o = 0; o < octaves; o++) {
      maxAmplitude += amp;
      amp *= gain;
    }
  }

  let peak = 0;

  for (let y = 0; y < size; y++) {
    const ny = (y / (size - 1)) * 2 - 1;
    for (let x = 0; x < size; x++) {
      const nx = (x / (size - 1)) * 2 - 1;

      // Warp the radius before it is masked, so the foot of the range
      // wanders in and out instead of describing a circle around the
      // viewer - a circular rim is the one thing that would give away that
      // the whole world is centred on the mountain.
      const warpX = fbm(warpNoise, nx * 0.7, ny * 0.7, 3);
      const warpY = fbm(warpNoise, nx * 0.7 + 3.1, ny * 0.7 - 9.4, 3);
      const wx = nx + warpX * warpAmount;
      const wy = ny + warpY * warpAmount;
      const r = Math.sqrt(wx * wx + wy * wy);

      const t = Math.min(1, Math.max(0, (r - innerRadius) / Math.max(1e-6, outerRadius - innerRadius)));
      // Smoothstep, not the raw ramp: the foot of a range is a curve, and a
      // linear mask puts a visible crease all the way round where the plain
      // stops being flat.
      const mask = t * t * (3 - 2 * t);
      if (mask <= 0) continue;

      let amplitude = 1;
      let freq = frequency;
      let ridgedSum = 0;
      for (let o = 0; o < octaves; o++) {
        const n = 1 - Math.abs(noise.noise2D(nx * freq, ny * freq));
        ridgedSum += n * n * amplitude;
        freq *= lacunarity;
        amplitude *= gain;
      }
      const ridged = ridgedSum / maxAmplitude;

      // A separate slow stream so whole stretches of the range are high and
      // others low. Without it every peak comes out the same height and the
      // skyline reads as a saw blade.
      const mass = 0.5 + 0.5 * fbm(massNoise, nx * massFrequency + 5.5, ny * massFrequency - 2.5, 3);

      const h = mask * (baseMass + (1 - baseMass) * ridged) * (0.45 + 0.55 * mass);

      heights[y * size + x] = h;
      if (h > peak) peak = h;
    }
  }

  if (peak > 0) {
    for (let i = 0; i < heights.length; i++) heights[i] /= peak;
  }

  return boxBlur3x3(boxBlur3x3(heights, size), size);
}
