import * as THREE from "three";
import type { TerrainSampler } from "./terrain-sampler";

export interface CameraRigOptions {
  camera: THREE.PerspectiveCamera;
  /**
   * Trail's full control-point chain (TrailResult.controlPoints). Not flown -
   * only averaged, to work out which flank of the mountain the climb is
   * drawn on so the shot can stand on that side of it.
   */
  controlPoints: THREE.Vector3[];
  worldSize: number;
  maxHeight: number;
  /** Same sampler the trail uses - the camera clears the same surface the line follows. */
  sampler: TerrainSampler;
  /**
   * World units the camera slides to each side of the ascent across the
   * whole climb. Total travel is twice this.
   */
  dollyDistance?: number;
  /**
   * How much of the dolly the look-at target carries with it, 0..1. At 0 the
   * camera arcs around a pinned target and the massif stays dead centre; at
   * 1 it trucks and the massif slides the full width of the move. In
   * between, the mountain drifts a little while the parallax still reads.
   */
  lookAtFollow?: number;
  /** Minimum world-unit clearance kept above terrain directly under the camera. */
  minClearance?: number;
  /** How fast `current` chases `target` each update(), 0..1. */
  damping?: number;
}

/**
 * One end of the ascent - the three knobs that decide a shot, plus the lens.
 *
 * Distance and height are fractions rather than world units so the whole
 * move rescales with the massif if WORLD_SIZE/MAX_HEIGHT in scene/index.ts
 * ever change. At today's scale (worldSize 620, maxHeight 170) multiply
 * distance by 620 and height by 170 to read them in world units.
 */
export interface Shot {
  /** How far the camera stands from the summit axis, x worldSize. */
  distance: number;
  /** How high it sits, x maxHeight. The terrain tops out at 1. */
  height: number;
  /** Vertical angle in degrees. Positive looks up, negative looks down. */
  pitch: number;
  /** Vertical field of view in degrees. Lower is longer glass - tighter zoom. */
  fov: number;
}

/**
 * Scroll takes the camera from one of these to the other, and that is the
 * entire move: a crane straight up a fixed bearing. It does not track the
 * switchbacks around the flank - that is the trail's job, and the camera
 * doing it too is what made the old rig read as a helicopter.
 *
 * BASE sits low and close, looking up at the mountain, which is what
 * "before the climb" looks like. SUMMIT ends level with the top rather than
 * above it: from above, the peak lands mid-frame behind the summit copy and
 * takes the flag with it, and the shot is mostly empty sky. The camera also
 * closes in as it rises, because a single distance cannot serve both ends -
 * the base needs width, the summit is a point on the axis and goes small.
 *
 * What this framing gives up: the trail's first switchback swings out to 0.8
 * of the massif's half width, which at 16:9 only clears the frame edge from
 * about 0.8 of the world back - so at BASE's 0.64 the bottom of the climb
 * starts outside the frame and the line rises into it. That is the trade for
 * the zoom, and it costs little, because the drawn head - the part anyone is
 * actually watching - climbs as the camera does. Framing all of it at once
 * was never on the table anyway: the switchbacks wrap about 172 degrees of
 * the massif, so some of the line is behind the mountain from any bearing.
 *
 * All of which is about the wide route. Below FIT_LIMIT_ASPECT the trail
 * draws its narrow one instead, which is composed to sit inside a frame this
 * shot can no longer widen.
 */
const BASE_SHOT: Shot = { distance: 0.64, height: 0.38, pitch: -5.9, fov: 35 };
const SUMMIT_SHOT: Shot = { distance: 0.5, height: 1.16, pitch: -10.4, fov: 35 };

/**
 * The frame the two shots above are composed for. Wider than this and
 * nothing below runs; narrower - a phone held upright - and the shot has to
 * be rebuilt for the frame it actually landed in.
 */
const REFERENCE_ASPECT = 16 / 9;

/**
 * How far the lens is allowed to open to win that width back. Past about
 * here the massif starts leaning away at the frame edges and reads as a
 * wide-angle photograph of a mountain rather than a mountain.
 */
const MAX_FIT_FOV = 58;

/**
 * And how far the camera may back off for the rest of it. Capped because
 * standoff is paid for in fog, not in pixels: the scene's FogExp2 runs at
 * density 0.0009 (SKY_DEFAULTS.fogDensity in scene/sky.ts), so the base
 * shot's 397 units sit under about 12% fog, 1.45x of it under 25%, and
 * twice it under 46% - at which point the mountain we backed up to see is
 * half dissolved into the sky behind it.
 */
const MAX_FIT_DISTANCE_SCALE = 1.45;

/**
 * The aspect at which both budgets above are exactly spent.
 *
 * Down to here, fitToViewport wins the lost width back in full: the shot is
 * reframed, but it still sees the same slice of the world it was composed
 * to see. Below here the lens is already at MAX_FIT_FOV and the standoff at
 * MAX_FIT_DISTANCE_SCALE, and every further degree of narrowness comes
 * straight off the width of world in frame - which is the point at which
 * anything laid out to the world's own scale, the trail's switchbacks above
 * all, has to be drawn narrower instead of just framed differently. That is
 * what scene/trail.ts routes by.
 *
 * Derived from the caps rather than written down as 0.7 so that it moves
 * when they are retuned. At today's values 16:9 / (1.45 x tan(29) /
 * tan(17.5)) = 0.697, which puts every phone held upright on the near side
 * of it and a tablet in portrait (0.75) on the far side - correctly, since
 * at 0.75 the shot still has fit left to spend.
 */
export const FIT_LIMIT_ASPECT =
  REFERENCE_ASPECT /
  (MAX_FIT_DISTANCE_SCALE *
    (Math.tan(THREE.MathUtils.degToRad(MAX_FIT_FOV / 2)) /
      Math.tan(THREE.MathUtils.degToRad(BASE_SHOT.fov / 2))));

/**
 * Reframes a shot for a viewport narrower than the one it was composed for.
 *
 * three's `fov` is the *vertical* angle, and it is the only one the camera
 * stores - the horizontal angle falls out of it and the aspect ratio. So a
 * fov left alone across a resize does not hold the framing steady, it holds
 * the *height* of the framing steady and lets the width go wherever the
 * viewport takes it. On a phone in portrait (aspect about 0.46 against the
 * 1.78 these shots were cut for) that is a horizontal view of roughly 17
 * degrees instead of 59: at the base shot's standoff, about 115 world units
 * of a 620-wide massif, which is not a mountain, it is a wall of rock.
 *
 * Closing that gap outright is not on the table - holding 59 degrees across
 * at 0.46 needs a 101-degree lens - so the shortfall is split, the lens
 * taking as much as MAX_FIT_FOV allows and the standoff carrying what is
 * left up to MAX_FIT_DISTANCE_SCALE. Both caps bind on a phone, so a phone
 * does not get the desktop's width back; it gets enough of the massif
 * either side of the summit axis to read as one.
 *
 * Derived from the live fov rather than from BASE_SHOT's 35 so that the
 * ?camera panel keeps working the way it reads: tune the shot for the
 * desktop frame, and the narrow frame re-derives from whatever you tuned.
 */
function fitToViewport(aspect: number, fov: number): { fov: number; distanceScale: number } {
  // How many times wider the frame needs to see than it currently does.
  // Written as `> 1` rather than `<= 1` so that a degenerate aspect - a
  // zero-height window, a camera read before its first resize - falls
  // through to the untouched shot instead of propagating a NaN into the
  // projection matrix.
  const deficit = REFERENCE_ASPECT / aspect;
  if (!(deficit > 1)) return { fov, distanceScale: 1 };

  // Both ends in tangent space, because that is where field of view is
  // linear: doubling the visible width doubles tan(half angle), not the
  // angle. Doing this in degrees would under-open the lens badly by the
  // time it is this wide.
  const half = Math.tan(THREE.MathUtils.degToRad(fov / 2));
  const maxHalf = Math.tan(THREE.MathUtils.degToRad(Math.max(fov, MAX_FIT_FOV) / 2));

  const lens = Math.min(deficit, maxHalf / half);
  return {
    fov: 2 * THREE.MathUtils.radToDeg(Math.atan(half * lens)),
    distanceScale: Math.min(deficit / lens, MAX_FIT_DISTANCE_SCALE),
  };
}

export interface CameraRig {
  /** Sets the target ascent progress (0..1). Camera does not jump here - see damping. */
  setProgress: (t: number) => void;
  /**
   * Places the camera at `t` outright, with no damping run-up.
   *
   * Damping is the right behaviour for scroll, where the target moves a
   * little at a time and the lag reads as weight. It is the wrong behaviour
   * for the two moments where progress arrives all at once instead: a route
   * change back onto the climb (the rig is being mounted at whatever offset
   * the page restored to), and a scripted return to the establishing shot,
   * which drives its own easing frame by frame and must not have a second
   * one applied on top of it.
   */
  jumpTo: (t: number) => void;
  /** Advances the damped progress and repositions the camera. Call once per frame. */
  update: () => void;
  /** The current damped progress, in case callers want to sync other effects to it. */
  currentProgress: () => number;
  /**
   * The two ends of the crane, live. Mutating a field re-frames the camera
   * on the next update() rather than at the next reload, which is what the
   * ?camera tuning panel drives - and what makes the numbers above worth
   * tuning by hand at all.
   */
  shots: { base: Shot; summit: Shot };
  /**
   * The compass direction (x, z) of the flank the shot stands on, derived
   * from the trail rather than written down - see trailFlankDirection().
   *
   * Published because the sun has the same problem the camera does and must
   * not solve it independently: a bearing hard-coded in the sky would go on
   * pointing at the old flank the first time the trail is retuned, and the
   * mountain would start throwing its shadow away from the lens.
   */
  flank: THREE.Vector2;
}

/**
 * The compass direction, in the XZ plane, of the flank the trail is drawn
 * on - the mean of its control points, normalised.
 *
 * Derived rather than written down as an angle because the two have to
 * agree: the trail's switchback legs (LEG_ANGLES in trail.ts) put the whole
 * climb on one side of the massif, and a hard-coded bearing here would go on
 * pointing at the old side the first time those are retuned, leaving the
 * camera craning up the blank face with the animation happening behind it.
 */
function trailFlankDirection(controlPoints: THREE.Vector3[]): THREE.Vector2 {
  const mean = new THREE.Vector2();
  for (const p of controlPoints) mean.x += p.x, mean.y += p.z;
  if (controlPoints.length > 0) mean.divideScalar(controlPoints.length);
  // A path that wraps the summit evenly has no flank to speak of; the far
  // side of the +Z axis is as good a shot as any other.
  return mean.length() > 1e-3 ? mean.normalize() : new THREE.Vector2(0, 1);
}

/**
 * Owns the scene camera's position/orientation across the ascent.
 *
 * The camera stands off the flank the trail is drawn on and scroll cranes it
 * from the foot of the mountain to just over the summit, with a slight
 * sideways drift for parallax. It used to fly the trail's own spiral - a
 * chase curve offset outward and up from the line - which put the viewer on
 * a banking helicopter ride around the massif for the length of the page.
 * The climb is told by the trail drawing itself and the flag planting at the
 * summit; the camera rises with it rather than chasing it.
 *
 * Positions are driven by an internally-damped `current` progress chasing
 * the externally-set `target`, so the rise glides rather than snaps -
 * callers must call `update()` every frame for the damping to advance.
 */
export function createCameraRig(options: CameraRigOptions): CameraRig {
  const dollyDistance = options.dollyDistance ?? options.worldSize * 0.05;
  const lookAtFollow = options.lookAtFollow ?? 0.35;
  const minClearance = options.minClearance ?? 18;
  const damping = options.damping ?? 0.04;

  const flank = trailFlankDirection(options.controlPoints);

  // Perpendicular to the bearing, in the ground plane. Taken from the
  // bearing rather than from the current view direction because the view
  // pitches steadily downward over the crane, and a right vector derived
  // from it would tilt the dolly with it - the sideways drift would start
  // sliding the horizon.
  const right = new THREE.Vector3(-flank.x, 0, -flank.y)
    .cross(new THREE.Vector3(0, 1, 0))
    .normalize();

  let target = 0;
  let current = 0;

  const position = new THREE.Vector3();
  const lookAt = new THREE.Vector3();
  // Straight at the summit axis, in the ground plane. Pitch tilts the aim
  // off this.
  const forward = new THREE.Vector3(-flank.x, 0, -flank.y);
  const aim = new THREE.Vector3();

  const shots = { base: { ...BASE_SHOT }, summit: { ...SUMMIT_SHOT } };

  const setProgress = (t: number) => {
    target = THREE.MathUtils.clamp(t, 0, 1);
  };

  const jumpTo = (t: number) => {
    target = THREE.MathUtils.clamp(t, 0, 1);
    current = target;
  };

  const update = () => {
    current += (target - current) * damping;

    // Smoothstepped rather than linear so the crane settles at both ends of
    // the page instead of still travelling when the scroll stops.
    const eased = THREE.MathUtils.smoothstep(current, 0, 1);
    const lateral = (eased * 2 - 1) * dollyDistance;

    // Read every frame rather than at construction: the correction has to
    // survive a phone being turned on its side, and resize() in
    // scene/index.ts has already put the new ratio on the camera by the
    // time we get here.
    const fit = fitToViewport(
      options.camera.aspect,
      THREE.MathUtils.lerp(shots.base.fov, shots.summit.fov, eased),
    );

    const distance =
      options.worldSize *
      THREE.MathUtils.lerp(shots.base.distance, shots.summit.distance, eased) *
      fit.distanceScale;
    const height =
      options.maxHeight * THREE.MathUtils.lerp(shots.base.height, shots.summit.height, eased);
    const pitch = THREE.MathUtils.degToRad(
      THREE.MathUtils.lerp(shots.base.pitch, shots.summit.pitch, eased),
    );
    const fov = fit.fov;

    position.set(flank.x * distance, height, flank.y * distance);
    position.addScaledVector(right, lateral);

    // Matters at the bottom of the crane now, not just in principle: the
    // base shot sits low enough that the apron under it is within a stone's
    // throw of the lens.
    const groundHeight = options.sampler.heightAt(position.x, position.z);
    if (position.y < groundHeight + minClearance) {
      position.y = groundHeight + minClearance;
    }

    // Aimed relative to the camera now that pitch, not a target height, sets
    // the vertical angle. The sideways component is what is left of the
    // dolly after the target has carried its share of it: at lookAtFollow 1
    // the aim moves with the camera and the massif slides, at 0 it swings
    // back onto the axis and the massif stays put.
    aim.copy(forward).multiplyScalar(Math.cos(pitch));
    aim.y = Math.sin(pitch);
    lookAt.copy(position).addScaledVector(aim, distance);
    lookAt.addScaledVector(right, lateral * (lookAtFollow - 1));

    options.camera.position.copy(position);
    options.camera.lookAt(lookAt);

    // Guarded because it rebuilds the projection matrix, and the two shots
    // share a lens unless someone deliberately splits them.
    if (Math.abs(options.camera.fov - fov) > 1e-4) {
      options.camera.fov = fov;
      options.camera.updateProjectionMatrix();
    }
  };

  return { setProgress, jumpTo, update, currentProgress: () => current, shots, flank };
}
