import * as THREE from "three";

export function isWebGL2Available(): boolean {
  try {
    const canvas = document.createElement("canvas");
    return !!(window.WebGL2RenderingContext && canvas.getContext("webgl2"));
  } catch {
    return false;
  }
}

export interface RendererSetup {
  renderer: THREE.WebGLRenderer;
  canvas: HTMLCanvasElement;
}

export interface RendererOptions {
  /** Device pixel ratio ceiling - kept lower on mobile so fill-rate stays cheap. */
  maxDpr?: number;
}

/**
 * Creates the WebGL2 renderer and its canvas, fixed behind all page
 * content. Returns null when WebGL2 isn't available so the caller can
 * leave the CSS fallback in place instead of half-initialising a scene.
 */
export function createRenderer(options: RendererOptions = {}): RendererSetup | null {
  if (!isWebGL2Available()) return null;

  const canvas = document.createElement("canvas");
  canvas.className = "scene-canvas";
  Object.assign(canvas.style, {
    position: "fixed",
    inset: "0",
    zIndex: "var(--z-canvas)",
    pointerEvents: "none",
  });

  const renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: true,
    powerPreference: "high-performance",
  });

  renderer.setPixelRatio(Math.min(window.devicePixelRatio, options.maxDpr ?? 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.0;
  renderer.outputColorSpace = THREE.SRGBColorSpace;

  return { renderer, canvas };
}
