import * as THREE from "three";

/**
 * The one texture the terrain needs, and the promise that says it arrived.
 *
 * Four surface grains packed a channel each - R rock, G snow, B scree,
 * A tundra. Built by scripts/pack-terrain-detail.mjs, which is also where
 * the prompts that generated the plates are written down.
 */
const DETAIL_URL = `${import.meta.env.BASE_URL}textures/terrain-detail.webp`;

export interface TerrainTextures {
  /**
   * Live from the first call. three fills the GPU texture in when the
   * download lands, so a material can hold this from the moment it is
   * built - `ready` is only for callers that need to know WHEN.
   */
  detail: THREE.Texture;
  /**
   * Resolves when the map is on the GPU, and resolves - never rejects - if
   * it never arrives. A visitor whose texture 404s gets the untextured
   * mountain, which is the picture this scene drew before the map existed;
   * holding the boot gate up forever over it would be the worse failure.
   */
  ready: Promise<void>;
}

/**
 * `anisotropy` is the one setting here that is not free, and it is the one
 * that matters most. A mountainside is the grazing-angle case textbooks
 * use: near the horizon a screen pixel covers a long thin strip of texture,
 * and trilinear filtering answers that with a square - so it picks a mip
 * far coarser than the strip is wide and the whole lower slope goes to
 * mush. 4x is where that stops being visible here; 8x and 16x cost more
 * and change nothing at this camera distance.
 */
export function loadTerrainTextures(
  renderer: THREE.WebGLRenderer,
  options: { anisotropy?: number } = {},
): TerrainTextures {
  const loader = new THREE.TextureLoader();

  let settle: () => void;
  const ready = new Promise<void>((resolve) => {
    settle = resolve;
  });

  const detail = loader.load(
    DETAIL_URL,
    () => settle(),
    undefined,
    () => {
      if (import.meta.env.DEV) {
        console.warn(`[textures] ${DETAIL_URL} did not load - terrain falls back to flat grain.`);
      }
      settle();
    },
  );

  detail.wrapS = THREE.RepeatWrapping;
  detail.wrapT = THREE.RepeatWrapping;
  // NOT SRGBColorSpace. These channels are a high-passed grain centred on
  // 0.5, not a colour - decoding them as sRGB would bend that centre down
  // to about 0.21 and darken every surface on the mountain by a factor the
  // shader constants know nothing about.
  detail.colorSpace = THREE.NoColorSpace;
  detail.anisotropy = Math.max(1, Math.min(options.anisotropy ?? 4, renderer.capabilities.getMaxAnisotropy()));

  return { detail, ready };
}
