import * as THREE from "three";
import { generateHeightmap } from "./heightmap";
import { createTerrainMaterial, type TerrainMaterialOptions } from "./materials/terrain.glsl";
import { TerrainSampler } from "./terrain-sampler";

export interface TerrainOptions {
  /** Full plane extent. Can be bigger than massifWidth/massifDepth to grow a lowland apron around the massif in the same mesh. */
  width: number;
  depth: number;
  /** Plane subdivisions per side. Vertex grid is (segments + 1)^2. */
  segments?: number;
  maxHeight: number;
  seed: number;
  rockColor: THREE.Color;
  snowColor: THREE.Color;
  snowlineHeight: number;
  /**
   * Everything else the surface material takes - the grain map, the
   * treeline, the scree band, the detail bump. Passed through rather than
   * restated field by field, so adding a knob to the material does not
   * mean adding the same knob here and in every caller.
   */
  surface?: Omit<TerrainMaterialOptions, "rockColor" | "snowColor" | "snowlineHeight">;
  /** The massif's own footprint within width/depth. Defaults to width/depth - i.e. the plane IS the massif, no lowland apron. */
  massifWidth?: number;
  massifDepth?: number;
  /** 0..1-normalized amplitude of rolling-hill detail in the lowland apron. 0 (default) = flat beyond the massif. */
  lowlandAmplitude?: number;
  lowlandFrequency?: number;
  /**
   * A ready-made 0..1 heightmap to displace with, in place of generating
   * one. This is how the baked maps in public/heightmaps get used, and it
   * is also how the far range - which is not a massif and has a generator
   * of its own - is built by this same function, with the same material,
   * the same normals and the same snowline treatment as the near one.
   *
   * It must be (segments + 1)^2 samples. Anything else is a caller bug and
   * throws here rather than displacing a torn mesh.
   */
  heightmap?: Float32Array;
}

export interface TerrainResult {
  mesh: THREE.Mesh;
  geometry: THREE.PlaneGeometry;
  /** Normalized 0..1 heightmap, as generated - kept for tooling/debug only. */
  heightmap: Float32Array;
  /**
   * The final world-space Y of every vertex: post-falloff, post-scale,
   * post-blur, exactly what was written into the position attribute. This
   * is the array the sampler reads, which is why the sampler and the mesh
   * cannot disagree.
   */
  heights: Float32Array;
  resolution: number;
  maxHeight: number;
  /** The one and only height lookup for this terrain. */
  sampler: TerrainSampler;
}

/**
 * PlaneGeometry displaced by a ridged-multifractal heightmap. Stays indexed
 * (no toNonIndexed, no flatShading) and uses computeVertexNormals so
 * lighting is smooth across the whole silhouette - that's what removes the
 * faceted look at this vertex density.
 */
export function createTerrain(options: TerrainOptions): TerrainResult {
  const segments = options.segments ?? 384;
  const resolution = segments + 1;

  if (options.heightmap && options.heightmap.length !== resolution * resolution) {
    throw new Error(
      `createTerrain: heightmap has ${options.heightmap.length} samples, ` +
        `but ${segments} segments needs ${resolution * resolution}`,
    );
  }

  const heightmap =
    options.heightmap ??
    generateHeightmap({
      resolution,
      seed: options.seed,
      worldWidth: options.width,
      massifWidth: options.massifWidth ?? options.width,
      lowlandAmplitude: options.lowlandAmplitude,
      lowlandFrequency: options.lowlandFrequency,
    });

  const geometry = new THREE.PlaneGeometry(options.width, options.depth, segments, segments);
  geometry.rotateX(-Math.PI / 2);

  // Build the world-space heights *first*, then displace from that array, so
  // the array the sampler reads and the vertices the camera sees are the same
  // numbers by construction rather than by a matching formula in two places.
  const heights = new Float32Array(heightmap.length);
  for (let i = 0; i < heights.length; i++) heights[i] = heightmap[i] * options.maxHeight;

  const position = geometry.attributes.position;
  for (let i = 0; i < position.count; i++) {
    position.setY(i, heights[i]);
  }
  position.needsUpdate = true;

  geometry.computeVertexNormals();
  geometry.computeBoundingBox();
  geometry.computeBoundingSphere();

  const material = createTerrainMaterial({
    ...options.surface,
    rockColor: options.rockColor,
    snowColor: options.snowColor,
    snowlineHeight: options.snowlineHeight,
  });

  const mesh = new THREE.Mesh(geometry, material);

  const sampler = new TerrainSampler({
    heights,
    resolution,
    width: options.width,
    depth: options.depth,
  });

  return { mesh, geometry, heightmap, heights, resolution, maxHeight: options.maxHeight, sampler };
}
